function _safeParseLS(key){
  try{
    var raw = localStorage.getItem(key);
    if(!raw) return null;
    return JSON.parse(raw);
  }catch(e){ return null; }
}
/** Load best game progress across old keys so HTML updates never wipe coins */
function loadBestGameState(){
  var best = null;
  var bestCoins = -1;
  STORAGE_GAME_LEGACY.forEach(function(k){
    var s = _safeParseLS(k);
    if(!s || typeof s !== 'object') return;
    var c = parseInt(s.coins,10)||0;
    var planted = 0;
    if(s.gardens){
      Object.keys(s.gardens).forEach(function(id){
        var p = (s.gardens[id]&&s.gardens[id].planted)||[];
        for(var i=0;i<p.length;i++) if(p[i]) planted++;
      });
    }
    var score = c * 1000 + planted;
    if(score > bestCoins){ bestCoins = score; best = s; }
  });
  if(!best) best = {coins:0, gardens:{}};
  if(typeof best.coins !== 'number') best.coins = parseInt(best.coins,10)||0;
  if(!best.gardens) best.gardens = {};
  return best;
}
function loadBestMeta(){
  var best = null;
  var bestScore = -1;
  STORAGE_META_LEGACY.forEach(function(k){
    var m = _safeParseLS(k);
    if(!m || typeof m !== 'object') return;
    var score = (m.streak||0)*10 + Object.keys(m.badges||{}).length*5 + ((m.milad&&m.milad.total)||0) + ((m.quizBoard&&m.quizBoard.length)||0)*3 + ((m.miladBoard&&m.miladBoard.length)||0)*3;
    if(m.playerName) score += 20;
    if(score >= bestScore){ bestScore = score; best = m; }
  });
  if(!best) best = {streak:0,lastPlay:null,dailyCount:0,dailyDate:null,badges:{},sound:true};
  if(!best.badges) best.badges = {};
  return best;
}
function loadBestQuranData(){
  for(var i=0;i<STORAGE_DATA_LEGACY.length;i++){
    var d = _safeParseLS(STORAGE_DATA_LEGACY[i]);
    if(d && typeof d === 'object' && Object.keys(d).length) return d;
  }
  return null;
}
