/* Keep back buttons as icon — I18N must not replace them */
function ensureBackIcons(){
  var iconHtml = '<img src="icons/back.png" alt="Back" class="back-ico">';
  var nodes = document.querySelectorAll(
    'button.back-btn, button.back-btn-ico, button.home-back-hub, button[id*="Back"], button[id*="back"]'
  );
  nodes.forEach(function(btn){
    if(btn.id === 'gameQuitBtn') return; // not a back icon
    // skip if not a navigation back
    var id = (btn.id||'');
    var cls = (btn.className||'');
    if(id.indexOf('ack') === -1 && id.indexOf('Back') === -1 && cls.indexOf('back') === -1) return;
    if(btn.querySelector && btn.querySelector('img.back-ico')) {
      // still strip text
      Array.prototype.slice.call(btn.childNodes).forEach(function(n){
        if(n.nodeType === 3) n.textContent = '';
      });
      return;
    }
    btn.innerHTML = iconHtml;
    btn.setAttribute('aria-label', 'Back');
    btn.classList.add('back-btn-ico');
    if(btn.hasAttribute('data-i18n')) btn.removeAttribute('data-i18n');
  });
}


/* Settings screen tiles */
function updateSettingsSoundUI(){
  var st = document.getElementById('settingsSoundState');
  if(!st) return;
  var on = (typeof meta==='undefined' || meta.sound !== false);
  st.textContent = on ? 'ON' : 'OFF';
  st.style.color = on ? '#86efac' : '#fca5a5';
}

function isAppFullscreen(){
  return !!(document.fullscreenElement || document.webkitFullscreenElement || document.msFullscreenElement);
}
function updateFsUI(){
  var st = document.getElementById('settingsFsState');
  if(!st) return;
  var on = isAppFullscreen();
  st.textContent = on ? 'ON' : 'OFF';
  st.style.color = on ? '#86efac' : '#fca5a5';
}
function toggleAppFullscreen(){
  try{
    if(isAppFullscreen()){
      var exit = document.exitFullscreen || document.webkitExitFullscreen || document.msExitFullscreen;
      if(exit) exit.call(document);
    } else {
      var el = document.documentElement;
      var req = el.requestFullscreen || el.webkitRequestFullscreen || el.msRequestFullscreen;
      if(req) req.call(el);
      else {
        alert('இந்த browser Full Screen support பண்ணாது');
        return;
      }
    }
  }catch(e){
    console.warn('fs', e);
    alert('Full Screen fail: ' + (e && e.message ? e.message : e));
  }
  setTimeout(updateFsUI, 200);
}
document.addEventListener('fullscreenchange', function(){ try{ updateFsUI(); }catch(e){} });
document.addEventListener('webkitfullscreenchange', function(){ try{ updateFsUI(); }catch(e){} });

function initSettingsScreen(){
  updateSettingsSoundUI();
  try{ if(typeof renderThemeGrid==='function') renderThemeGrid(); }catch(e){}
  if(window.__settingsBound) return;
  window.__settingsBound = true;
  document.addEventListener('click', function(ev){
    var tile = ev.target.closest && ev.target.closest('.settings-tile');
    if(!tile) return;
    var set = tile.getAttribute('data-set');
    if(set==='font'){
      try{ if(typeof switchScreen==='function') switchScreen('screenFont'); }catch(e){}
      return;
    }
    if(set==='themes'){
      var p = document.getElementById('settingsThemesPanel');
      if(p) p.scrollIntoView({behavior:'smooth', block:'start'});
      try{ if(typeof renderThemeGrid==='function') renderThemeGrid(); }catch(e){}
      return;
    }
    if(set==='about'){
      try{
        var ov = document.getElementById('adminOverlay');
        if(ov) ov.classList.add('active');
      }catch(e){}
      return;
    }
    if(set==='sound'){
      try{
        if(typeof meta!=='undefined'){
          meta.sound = !(meta.sound !== false);
          if(typeof AudioFX!=='undefined') AudioFX.enabled = meta.sound;
          if(typeof saveMeta==='function') saveMeta();
          if(typeof updateHeader==='function') updateHeader();
        }
        updateSettingsSoundUI();
      }catch(e){}
      return;
    }
    if(set==='lang'){
      try{
        if(typeof I18N!=='undefined' && typeof I18N.toggle==='function') I18N.toggle();
        else {
          var hb = document.getElementById('headerLangBtn');
          if(hb) hb.click();
        }
      }catch(e){}
      return;
    }
    if(set==='fullscreen'){
      try{ toggleAppFullscreen(); }catch(e){}
      return;
    }
  }, true);
}

