  4:  { name: "Lan Tana Lu",        start: {s:3,a:93},  end: {s:4,a:23},   surahs: [3,4] },
  5:  { name: "Wa'l-Muhsanat",      start: {s:4,a:24},  end: {s:4,a:147},  surahs: [4] },
  6:  { name: "La Yuhibbu-llah",    start: {s:4,a:148}, end: {s:5,a:81},   surahs: [4,5] },
