function renderPlotsGrid(){
  const grid = document.getElementById('plotsGrid');
  if(!grid) return;
  const _si = document.getElementById('surahSearchInput');
  const q = ((_si && _si.value)||'').trim().toLowerCase();
  // SURAH list only — Juz is a separate feature (not a surah filter)
  ensureLevelMeta();
  checkLevelCompletions();
  renderLevelBar();
  var def = getSurahLevelDef(selectedSurahLevel);
  let list = SURAH_META.filter(m=>{
    if(m.n < def.start || m.n > def.end) return false;
    if(!q) return true;
    return (m.en||'').toLowerCase().includes(q) || (m.ar||'').includes(q) || String(m.n).includes(q);
  });
  let currentId = null;
  for(const m of list){
    const id = surahIdForNum(m.n);
    const s = QURAN_DATA[id];
    if(!s || !s.ayat || !s.ayat.length){ if(!currentId) currentId = id; continue; }
    const g = state.gardens[id]||{planted:[]};
    const total = s.ayat.length;
    if(g.planted.filter(Boolean).length < total){ currentId = id; break; }
  }
  let totalStars=0, maxStars=list.length*3;
  var stLv = levelStats(selectedSurahLevel);
  var rankNow = meta.levelProgress.ranks[selectedSurahLevel];
  var unlockTxt = isLevelUnlocked(selectedSurahLevel)
    ? (stLv.complete
        ? ('✅ ' + _('msg_done_short') + ' ' + (RANK_LABEL[rankNow]||''))
        : (stLv.done + '/' + stLv.total + ' ' + _('lbl_surah')))
    : ('🔒 ' + _('lbl_locked'));
  let h = '<div class="level-map-title"><img src="icons/tree-64.png" class="title-tree" alt=""> Level ' + selectedSurahLevel + ' · ' + _('lbl_surah') + ' ' + def.start + '–' + def.end + ' <span class="slv-status">' + unlockTxt + '</span></div><div class="level-grid">';
  list.forEach(m=>{
    const id = surahIdForNum(m.n);
    const surah = QURAN_DATA[id];
    const hasData = !!(surah && surah.ayat && surah.ayat.length);
    const g = state.gardens[id]||{planted:[]};
    const total = hasData ? surah.ayat.length : (m.a||0);
    const P = hasData ? g.planted.filter(Boolean).length : 0;
    const done = hasData && total>0 && P>=total;
    const started = P>0;
    const isCurrent = id===currentId;
    let stars = done ? 3 : (P>0 ? Math.max(1, Math.round(P/total*3)) : 0);
    totalStars += stars;
    let cls = 'level-tile';
    if(done) cls += ' done';
    else if(isCurrent) cls += ' current';
    else if(started) cls += ' progress';
    else if(!hasData) cls += ' locked';
    else cls += ' locked';
    const num = m.n;
    const enName = String(m.en || ('Surah ' + num));
    let arName = String(m.ar || '');
    if(arName.indexOf('سُورَةُ') === 0) arName = arName.slice(6).trim();
    else if(arName.indexOf('سورة') === 0) arName = arName.slice(4).trim();
    let starsHtml = '';
    for(let s=1;s<=3;s++) starsHtml += s<=stars ? '⭐' : '☆';
    const badge = (isCurrent && !started) ? '<span class="level-new-badge">NEW!</span>' : '';
    const ayahLabel = m.a ? (m.a + ' ' + _('lbl_ayah')) : '';
    const inner =
      '<span class="level-num-badge">'+num+'</span>'+
      '<img src="icons/surah-72.png" alt="" class="level-surah-icon">';
    h += '<div class="'+cls+'" onclick="openGardenByNum('+m.n+')">'+badge+inner+
      '<div class="level-stars">'+starsHtml+'</div>'+
      '<div class="level-name-ar" dir="rtl">'+arName+'</div>'+
      '<div class="level-name">'+enName+'</div>'+
      (ayahLabel ? '<div class="level-ayahs">'+ayahLabel+'</div>' : '')+
      '</div>';
  });
  h += '</div><div class="level-progress-bar">⭐ '+totalStars+'/'+maxStars+'</div>';
  grid.innerHTML = h;
  updateHeader();
}

function stripBismillah(text, surahNum){
  if(!text) return '';
  var t = String(text).replace(/^\uFEFF/,'').trim();
  if(surahNum === 1 || surahNum === 9) return t;
  // Multiple Bismillah orthographies (Uthmani + IndoPak)
  t = t.replace(/^بِّ?سۡ?مِ[\s\u00A0]*ٱ?للَّ?هِ[\s\u00A0]*ٱ?لرَّحۡ?مَ[ـ\u0650]*ٰ?نِ[\s\u00A0]*ٱ?لرَّحِ[يىی]مِ[\s\u00A0]*/u, '');
  t = t.replace(/^بِسْمِ[\s\u00A0]+اللَّهِ[\s\u00A0]+الرَّحْمَٰنِ[\s\u00A0]+الرَّحِيمِ[\s\u00A0]*/u, '');
  t = t.replace(/^بسم الله الرحمن الرحيم[\s\u00A0]*/u, '');
  return t.trim();
}

async function ensureSurahLoaded(n){
  const id = surahIdForNum(n);
  if(QURAN_DATA[id] && QURAN_DATA[id].ayat && QURAN_DATA[id].ayat.length) return id;
  const meta = SURAH_META.find(m=>m.n===n);
  const endpoint = currentScript === 'uthmani'
    ? 'https://api.quran.com/api/v4/quran/verses/uthmani?chapter_number='+n
    : 'https://api.quran.com/api/v4/quran/verses/indopak?chapter_number='+n;
  const field = currentScript === 'uthmani' ? 'text_uthmani' : 'text_indopak';
  try {
    const [arRes, taRes] = await Promise.all([
      fetch(endpoint),
      fetch('https://api.alquran.cloud/v1/surah/'+n+'/ar.muyassar').catch(function(){return null}).then(function(){return {json:function(){return Promise.resolve({code:200,data:{ayahs:[]}})}}})
    ]);
    if(!arRes.ok) throw new Error('fail');
    const arData = await arRes.json();
    const verses = arData.verses || [];
    if(!verses.length) throw new Error('empty');
    let taList = [];
    if(taRes.ok){
      const taData = await taRes.json();
      taList = (taData.data && taData.data.ayahs || []).map(a=>a.text);
    }
    const ayat = verses.map((v,i)=>({
      ar: String(v[field]||'').replace(/^\uFEFF/,'').trim(),
      ta: taList[i]||''
    }));
    const newId = (n===1 && !QURAN_DATA.fatiha) ? 'fatiha' : 's'+n;
    QURAN_DATA[newId] = {
      nameAr: (meta&&meta.ar) || '',
      nameTa: n+'. '+((meta&&meta.en)||''),
      surahNum: n,
      ayat
    };
    if(!state.gardens[newId] || state.gardens[newId].planted.length !== ayat.length){
      state.gardens[newId] = {planted: Array(ayat.length).fill(false)};
    }
    saveData(); saveGame();
    return newId;
  } catch(e){
    alert(_('msg_surah_load_fail'));
    return null;
  }
}


/** Build full Juz ayah queue: start ayah → end ayah (all surahs in between) */
async function buildJuzAyahQueue(j){
  const m = JUZ_META[j];
  if(!m || !m.start || !m.end) return [];
  const queue = [];
  const surahNums = [];
  // consecutive surah numbers from start.s to end.s
  for(let sn = m.start.s; sn <= m.end.s; sn++) surahNums.push(sn);
  for(let si = 0; si < surahNums.length; si++){
    const sn = surahNums[si];
    const id = await ensureSurahLoaded(sn);
    if(!id || !QURAN_DATA[id] || !QURAN_DATA[id].ayat) continue;
    const s = QURAN_DATA[id];
    const ayat = s.ayat;
    let from = 1;
    let to = ayat.length;
    if(sn === m.start.s) from = m.start.a;
    if(sn === m.end.s) to = m.end.a;
    from = Math.max(1, from);
    to = Math.min(ayat.length, to);
    for(let a = from; a <= to; a++){
      const ay = ayat[a - 1];
      if(!ay) continue;
      queue.push({
        id: id,
        surahNum: s.surahNum || sn,
        ayahNum: a,
        nameTa: s.nameTa || s.nameEn || ('சூரா '+sn),
        nameAr: s.nameAr || '',
        ar: ay.ar || '',
        ta: ay.ta || ''
      });
    }
  }
  return queue;
}

/**
 * Tap Juz → show FULL juz from first ayah to last ayah
 * (like tapping Surah shows full surah)
 */
async function openJuzReading(j){
  const metaJ = (typeof JUZ_META !== 'undefined') ? JUZ_META[j] : null;
  if(!metaJ || !metaJ.start){
    alert(_('msg_juz_no_data').replace('{j}', String(j)));
    return;
  }
  const toast = document.createElement('div');
  toast.style.cssText = 'position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:#1a2340;border:1px solid rgba(255,255,255,.2);padding:12px 16px;border-radius:12px;z-index:9999;font-size:13px;font-weight:700;max-width:92%;text-align:center';
  toast.textContent = '⏳ ஜுஸ்வு '+j+' · முதல் ஆயத்து முதல் கடைசி வரை ஏற்றுகிறது...';
  document.body.appendChild(toast);
  try{
    stopContinuous();
    const queue = await buildJuzAyahQueue(j);
    if(!queue.length){
      toast.textContent = _('msg_juz_ayat_fail');
      setTimeout(function(){ toast.remove(); }, 2000);
      return;
    }
    contQueue = queue;
    contIndex = 0;
    contActiveSurahId = queue[0].id;
    contActiveAyat = queue.map(function(x){ return {ar:x.ar, ta:x.ta||'', ayahNum:x.ayahNum}; });
    window.__juzFullMode = true;
    window.__juzFullId = j;
    if(typeof currentJuzView !== 'undefined') currentJuzView = j;

    // Stay on ஜுஸ்வு screen only (no separate audio menu/screen)
    if(typeof switchScreen === 'function') switchScreen('screenJuz');
    try{
      const list = document.getElementById('juzSettingsList');
      if(list) list.style.display = 'none';
      const title = document.getElementById('juzScreenTitle');
      if(title){ title.style.display = 'block'; title.textContent = '📖 ஜுஸ்வு '+j+' · '+juzName(j); }
      const st = document.getElementById('juzSurahListTitle');
      if(st){ st.style.display = 'block'; st.textContent = juzStartLabel(j)+'  →  '+juzEndLabel(j)+' · '+queue.length+' ஆயத்து'; }
      const grid = document.getElementById('juzNumGrid');
      if(grid){ grid.style.display = 'none'; }
      const sgrid = document.getElementById('juzSurahGrid');
      if(sgrid){ sgrid.style.display = 'none'; }
      const bar = document.getElementById('juzPlayerBar');
      if(bar) bar.style.display = '';
      const load = document.getElementById('juzLoading');
      if(load) load.style.display = 'none';
      const panel = document.getElementById('juzAyahPanel');
      if(panel){
        panel.dataset.sid = '';
        panel.classList.add('show');
        panel.style.display = 'block';
      }
      // Back to 30 juz list
      let backRow = document.getElementById('juzReadBackBtn');
      if(!backRow){
        backRow = document.createElement('button');
        backRow.type = 'button';
        backRow.id = 'juzReadBackBtn';
        backRow.className = 'back-btn';
        backRow.textContent = _('msg_juz_list');
        backRow.style.marginBottom = '8px';
        const host = document.getElementById('screenJuz');
        if(host) host.insertBefore(backRow, host.firstChild.nextSibling);
      }
      backRow.style.display = '';
      backRow.onclick = function(){
        stopContinuous();
        window.__juzFullMode = false;
        if(bar) bar.style.display = 'none';
        if(panel){ panel.classList.remove('show'); panel.innerHTML = ''; panel.style.display = 'none'; }
        if(list) list.style.display = '';
        backRow.style.display = 'none';
        if(title) title.style.display = 'none';
        if(st) st.style.display = 'none';
        if(typeof renderJuzSettingsList === 'function') renderJuzSettingsList();
      };
      if(typeof updateJuzUI === 'function') updateJuzUI();
      if(typeof renderAyahPanel === 'function') renderAyahPanel();
    }catch(e){ console.warn(e); }

    toast.textContent = '▶️ ஜுஸ்வு '+j+' · '+queue.length+' ஆயத்து · '+juzStartLabel(j)+' முதல்';
    setTimeout(function(){ try{ toast.remove(); }catch(e){} }, 2000);
    // Auto-play from first ayah of juz to last
    if(typeof playContinuousAt === 'function') playContinuousAt(0);
  }catch(e){
    console.warn(e);
    toast.textContent = _('msg_juz_open_fail');
    setTimeout(function(){ toast.remove(); }, 1800);
  }
}



/* ===== Surah Level Path (30 / 5 chunks) ===== */
function getLevelChunkSize(totalAyat){
  return totalAyat > 30 ? 30 : 5;
}

function buildSurahLevels(totalAyat){
  const size = getLevelChunkSize(totalAyat);
  const levels = [];
  let start = 0;
  let n = 1;
  while(start < totalAyat){
    const end = Math.min(start + size, totalAyat);
    levels.push({
      level: n,
      start: start,      // 0-based inclusive
      end: end,          // 0-based exclusive
      count: end - start,
      reward: Math.max(10, (end - start) * 2)
    });
    start = end;
    n++;
  }
  return levels;
}

function levelStatus(g, lvl){
  if(!g || !g.planted) return { done:0, total:lvl.count, complete:false, unlocked:true };
  let done = 0;
  for(let i = lvl.start; i < lvl.end; i++){
    if(g.planted[i]) done++;
  }
  // unlock: first level always; next unlocks when previous complete
  return { done: done, total: lvl.count, complete: done >= lvl.count, unlocked: true };
}

function renderLevelPath(){
  const path = document.getElementById('levelPath');
  if(!path || !currentSurah || !QURAN_DATA[currentSurah]) return;
  const surah = QURAN_DATA[currentSurah];
  const g = state.gardens[currentSurah] || {planted:[]};
  const levels = buildSurahLevels(surah.ayat.length);
  path.innerHTML = '';

  // track line
  const rail = document.createElement('div');
  rail.className = 'lvl-rail';
  path.appendChild(rail);

  levels.forEach(function(lvl, idx){
    const st = levelStatus(g, lvl);
    // lock if previous incomplete
    let unlocked = idx === 0;
    if(idx > 0){
      const prev = levelStatus(g, levels[idx-1]);
      unlocked = prev.complete;
    }
    const row = document.createElement('div');
    row.className = 'lvl-row'
      + (st.complete ? ' done' : '')
      + (!unlocked ? ' locked' : '')
      + (unlocked && !st.complete ? ' next' : '');

    const pct = st.total ? Math.round((st.done/st.total)*100) : 0;
    const barInner = st.complete ? 100 : pct;

    let rewardIcon = '<span class="coin-spin coin-spin-sm"><img src="icons/coin.png" alt=""></span>';
    if(st.complete) rewardIcon = '<span class="coin-spin coin-spin-sm"><img src="icons/coin.png" alt=""></span>';
    else if(lvl.level % 5 === 0) rewardIcon = '<span class="coin-spin coin-spin-sm"><img src="icons/coin.png" alt=""></span>';
    else if(lvl.level % 3 === 0) rewardIcon = '<span class="coin-spin coin-spin-sm"><img src="icons/coin.png" alt=""></span>';

    row.innerHTML =
      '<div class="lvl-bar">' +
        '<div class="lvl-bar-fill" style="width:'+barInner+'%"></div>' +
        '<div class="lvl-bar-text">' +
          '<span class="lvl-num">'+lvl.level+'</span>' +
          '<span class="lvl-label">Level</span>' +
          '<span class="lvl-ayah">'+_('lbl_ayah')+' '+(lvl.start+1)+'–'+lvl.end+' · '+st.done+'/'+st.total+'</span>' +
        '</div>' +
      '</div>' +
      '<div class="lvl-reward'+(st.complete?' got':'')+'">' +
        '<div class="lvl-reward-icon">'+rewardIcon+'</div>' +
        '<div class="lvl-reward-val">'+(st.complete ? _('msg_done_short') : ('+'+lvl.reward))+'</div>' +
      '</div>';

    if(unlocked && !st.complete){
      row.onclick = function(){
        window.__levelStart = lvl.start;
        window.__levelEnd = lvl.end;
        for(let i = lvl.start; i < lvl.end; i++){
          if(!g.planted[i]){ openQuiz(i); return; }
        }
      };
    } else if(st.complete){
      row.onclick = function(){
        // review full level as a continuous round
        window.__levelStart = lvl.start;
        window.__levelEnd = lvl.end;
        openQuiz(lvl.start);
      };
    }

    path.appendChild(row);
  });
}


async function openGardenByNum(n){
  const loading = document.createElement('div');
  loading.id = 'surahLoadToast';
  loading.style.cssText = 'position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:#1a2340;border:1px solid var(--glass-border);padding:10px 18px;border-radius:12px;z-index:999;font-size:13px;font-weight:700';
  loading.textContent = '⏳ '+_('lbl_surah')+' '+n+' '+_('lbl_loading')+'...';
  document.body.appendChild(loading);
  const id = await ensureSurahLoaded(n);
  loading.remove();
  if(!id) return;
  openGarden(id);
}


function closeAllOverlays(){
  try{
    document.querySelectorAll('.overlay.active').forEach(function(el){ el.classList.remove('active'); });
    const mo = document.getElementById('menuOverlay');
    const sm = document.getElementById('sideMenu');
    if(mo) mo.classList.remove('open');
    if(sm) sm.classList.remove('open');
    if(currentAudio){ try{ currentAudio.pause(); }catch(e){} currentAudio=null; }
  }catch(e){}
}

function openGarden(id){
  closeAllOverlays();
  currentSurah = id;
  const s = QURAN_DATA[id];
  if(!s) return;
  window.__dotsPage = 0;
  document.getElementById('gardenNameAr').textContent = s.nameAr;
  document.getElementById('gardenNameTa').textContent = s.nameTa;
  renderTree(); renderDots(); try{ renderLevelPath(); }catch(e){} updateDailyUI();
  switchScreen('screenGarden');
  try{ window.scrollTo(0,0); document.getElementById('screenGarden').scrollTop = 0; }catch(e){}
}

function renderTree(){
  const surah = QURAN_DATA[currentSurah], g = state.gardens[currentSurah];
  const N = surah.ayat.length, P = g.planted.filter(Boolean).length;
  const pct = N > 0 ? Math.round(P / N * 100) : 0;
  const circumference = 2 * Math.PI * 50; // r=50
  const offset = circumference - (pct / 100) * circumference;
  const ring = document.getElementById('spRingFg');
  if(ring){
    ring.style.strokeDasharray = circumference;
    ring.style.strokeDashoffset = offset;
    ring.classList.toggle('done', P >= N && N > 0);
  }
  const pctEl = document.getElementById('spPct');
  if(pctEl) pctEl.textContent = pct + '%';
  let stars = 0;
  if(P >= N && N > 0) stars = 3;
  else if(P > 0) stars = Math.max(1, Math.round(P / N * 3));
  const starsEl = document.getElementById('spStars');
  if(starsEl){
    let h = '';
    for(let i = 1; i <= 3; i++) h += i <= stars ? '⭐' : '☆';
    starsEl.textContent = h;
  }
  const countEl = document.getElementById('spCount');
  if(countEl) countEl.textContent = P + ' / ' + N + ' ' + _('lbl_ayahs');
  const progressLabel = document.getElementById('progressLabel');
  if(progressLabel) progressLabel.textContent = P + ' / ' + N + ' ' + _('lbl_ayahs');
  document.getElementById('completeBanner').classList.toggle('show', P >= N && N > 0);
}
function renderDots(){
  const surah = QURAN_DATA[currentSurah], g = state.gardens[currentSurah];
  const wrap = document.getElementById('ayahDots');
  if(!wrap || !surah || !g) return;
  wrap.innerHTML = '';
  const total = surah.ayat.length;
  const PAGE = 40;
  let page = window.__dotsPage || 0;
  const maxPage = Math.max(0, Math.ceil(total / PAGE) - 1);
  if(page > maxPage) page = maxPage;
  window.__dotsPage = page;
  const start = page * PAGE;
  const end = Math.min(total, start + PAGE);

  // nav for large surahs
  if(total > PAGE){
    const nav = document.createElement('div');
    nav.style.cssText = 'width:100%;display:flex;justify-content:center;align-items:center;gap:10px;margin:6px 0 10px;flex-wrap:wrap';
    const prev = document.createElement('button');
    prev.type = 'button';
    prev.className = 'mode-btn';
    prev.textContent = _('msg_prev');
    prev.disabled = page <= 0;
    prev.onclick = function(){ window.__dotsPage = page - 1; renderDots(); try{wrap.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){} };
    const info = document.createElement('span');
    info.style.cssText = 'font-size:12px;font-weight:700;color:var(--text-dim)';
    info.textContent = (start+1) + '–' + end + ' / ' + total;
    const next = document.createElement('button');
    next.type = 'button';
    next.className = 'mode-btn';
    next.textContent = _('msg_next');
    next.disabled = page >= maxPage;
    next.onclick = function(){ window.__dotsPage = page + 1; renderDots(); try{wrap.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){} };
    nav.appendChild(prev); nav.appendChild(info); nav.appendChild(next);
    wrap.appendChild(nav);
  }

  for(let i = start; i < end; i++){
    const d = document.createElement('button');
    d.type = 'button';
    d.className = 'ayah-dot' + (g.planted[i] ? ' done' : '');
    d.textContent = g.planted[i] ? '✓' : String(i+1);
    d.setAttribute('aria-label', 'Ayah '+(i+1));
    (function(idx){
      d.onclick = function(){ if(!g.planted[idx]) openQuiz(idx); };
    })(i);
    wrap.appendChild(d);
  }
}

function openQuiz(index){
  stopContinuous();
  window.__qi = index;
  // if not inside a level round, treat as single-ayah round
  if(typeof window.__levelStart !== 'number' || typeof window.__levelEnd !== 'number'){
    window.__levelStart = index;
    window.__levelEnd = index + 1;
  }
  const surah = QURAN_DATA[currentSurah];
  const correct = surah.ayat[index];
  const label = document.getElementById('quizLabel');
  const ctx = document.getElementById('contextAyah');
  const opts = document.getElementById('optionsWrap');
  const audioWrap = document.getElementById('audioWrap');
  opts.innerHTML = ''; audioWrap.innerHTML = '';

  if(surah.surahNum){
    const ab = document.createElement('button');
    ab.className = 'audio-btn';
    ab.textContent = _('msg_listen_ayah');
    ab.onclick = function(){ playAudio(surah.surahNum, index+1, ab); };
    audioWrap.appendChild(ab);
  }

  if(quizMode === 'next'){
    label.textContent = _('msg_next_ayah')+' · '+_('lbl_ayah')+' '+(index+1);
    if(index === 0){
      // First ayah of surah — show surah name + ask for ayah 1
      setContextText(ctx, (surah.nameAr||'') + ' — ஆயத்து ১ ؟', null, surah.surahNum, 1);
    } else {
      // Context = previous ayah (1-based number = index)
      setContextText(ctx, surah.ayat[index-1].ar, surah.ayat[index-1].ta || null, surah.surahNum, index);
    }
    buildOptions(correct, opts, function(){ onCorrect(index); });
  } else if(quizMode === 'blank'){
    label.textContent = _('msg_fill_blank');
    const words = correct.ar.split(/\s+/).filter(Boolean);
    if(words.length < 2){
      setContextText(ctx, correct.ar, null, surah.surahNum, index+1);
      buildOptions(correct, opts, function(){ onCorrect(index); });
    } else {
      const hi = Math.floor(Math.random() * words.length);
      const blank = words[hi];
      setContextText(ctx, words.map(function(w,i){ return i===hi ? '______' : w; }).join(' '), null);
      let pool = [];
      Object.values(QURAN_DATA).forEach(s=> s.ayat.forEach(a=> a.ar.split(/\s+/).forEach(w=>{ if(w && w!==blank) pool.push(w); })));
      pool = shuffle(pool).slice(0,3);
      const choices = shuffle([blank].concat(pool));
      choices.forEach(ch=>{
        const b = document.createElement('button');
        b.className = 'opt-btn';
        b.textContent = ch;
        b.onclick = function(){
          if(ch === blank){ b.classList.add('correct'); AudioFX.playCorrect(); setTimeout(function(){ onCorrect(index); }, 350); }
          else { b.classList.add('wrong'); AudioFX.playWrong(); }
        };
        opts.appendChild(b);
      });
    }
  } else {
    label.textContent = _('msg_pick_ayah_meaning');
    ctx.textContent = '';
    const t = document.createElement('div');
    t.style.cssText = 'font-family:var(--font-ui);font-size:15px;direction:ltr;text-align:left;color:#fff';
    t.textContent = correct.ta || '(பொருள் இல்லை)';
    ctx.appendChild(t);
    buildOptions(correct, opts, function(){ onCorrect(index); });
  }
  document.getElementById('quizOverlay').classList.add('active');
}

function buildOptions(correct, wrap, onOk){
  let samePool = [], otherPool = [];
  const cur = QURAN_DATA[currentSurah];
  if(cur) cur.ayat.forEach(a=>{ if(a.ar !== correct.ar) samePool.push(a); });
  Object.keys(QURAN_DATA).forEach(id=>{
    if(id === currentSurah) return;
    QURAN_DATA[id].ayat.forEach(a=>{ if(a.ar !== correct.ar) otherPool.push(a); });
  });
  samePool = shuffle(samePool);
  otherPool = shuffle(otherPool);
  let pool = samePool.slice(0,3);
  if(pool.length < 3) pool = pool.concat(otherPool.slice(0, 3-pool.length));
  const options = shuffle([correct].concat(pool.slice(0,3)));
  wrap.innerHTML = '';
  options.forEach(opt=>{
    const b = document.createElement('button');
    b.className = 'opt-btn';
    // Options always plain Unicode (no spans) for correct joining + no QCF codes
    b.textContent = opt.ar;
    if(showMeaning && opt.ta){
      const m = document.createElement('div');
      m.className = 'ta-meaning';
      m.textContent = opt.ta;
      b.appendChild(m);
    }
    b.onclick = function(){
      if(opt.ar === correct.ar){ b.classList.add('correct'); AudioFX.playCorrect(); setTimeout(onOk, 350); }
      else { b.classList.add('wrong'); AudioFX.playWrong(); }
    };
    wrap.appendChild(b);
  });
}

function onCorrect(index){
  state.gardens[currentSurah].planted[index] = true;
  state.coins += 10;
  updateStreak(); addDaily(); saveGame();
  if(currentAudio){ try{ currentAudio.pause(); }catch(e){} currentAudio=null; }
  updateHeader();
  try{ renderTree(); }catch(e){}
  try{ renderDots(); }catch(e){}

  // Continuous round: stay in quiz until level range is fully done
  var start = (typeof window.__levelStart === 'number') ? window.__levelStart : 0;
  var end = (typeof window.__levelEnd === 'number') ? window.__levelEnd : (QURAN_DATA[currentSurah] ? QURAN_DATA[currentSurah].ayat.length : 0);
  var g = state.gardens[currentSurah];
  var next = -1;
  for(var i = start; i < end; i++){
    if(g && !g.planted[i]){ next = i; break; }
  }

  if(next >= 0){
    // same round — next ayah, no exit
    setTimeout(function(){ openQuiz(next); }, 280);
    return;
  }

  // Round complete
  window.__levelStart = null;
  window.__levelEnd = null;
  document.getElementById('quizOverlay').classList.remove('active');
  try{ renderLevelPath(); }catch(e){}
  try{
    var toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:linear-gradient(135deg,#059669,#10b981);color:#fff;padding:12px 18px;border-radius:14px;z-index:9999;font-weight:800;font-size:13px;box-shadow:0 8px 24px rgba(0,0,0,.25)';
    toast.textContent = _('msg_level_done');
    document.body.appendChild(toast);
    setTimeout(function(){ try{ toast.remove(); }catch(e){} }, 2200);
  }catch(e){}
}

function playAudio(surahNum, ayahNum, btn){
  stopContinuous();
  if(currentAudio){ currentAudio.pause(); currentAudio=null; }
  const s = String(surahNum).padStart(3,'0');
  const a = String(ayahNum).padStart(3,'0');
  const url = 'https://everyayah.com/data/Alafasy_128kbps/'+s+a+'.mp3';
  const audio = new Audio(url);
  currentAudio = audio;
  btn.textContent = _('msg_pause');
  audio.play().catch(function(){ alert(_('msg_audio_fail')); btn.textContent=_('msg_listen_ayah'); });
  audio.onended = function(){ btn.textContent=_('msg_listen_ayah'); currentAudio=null; };
  btn.onclick = function(){
    if(currentAudio){ currentAudio.pause(); currentAudio=null; btn.textContent=_('msg_listen_ayah');
      btn.onclick = function(){ playAudio(surahNum, ayahNum, btn); };
    }
  };
}

/* ===== Continuous / Juz-wise Audio Player (all 30 Juz) ===== */
let contQueue = [];
let contIndex = 0;
let contPlaying = false;
let contPaused = false;
let contActiveSurahId = null;
let contActiveAyat = null; // [{ar,ta,ayahNum}] for current playing surah
let currentJuzView = null; // null = juz list, number = surah list of that juz
let JUZ_CACHE = {}; // juzNum -> {surahs: [{id, surahNum, nameAr, nameEn, nameTa, ayat:[{ar,ta}]}]}

function buildSurahQueueFromObj(s){
  if(!s || !s.surahNum) return [];
  return s.ayat.map((a,i)=>({id:s.id||('s'+s.surahNum), surahNum:s.surahNum, ayahNum:i+1, nameTa:s.nameTa||s.nameEn||'', nameAr:s.nameAr||'', ar:a.ar, ta:a.ta||''}));
}

function buildSurahQueue(surahId){
  const s = QURAN_DATA[surahId];
  if(!s || !s.surahNum) return [];
  return s.ayat.map((a,i)=>({id:surahId, surahNum:s.surahNum, ayahNum:i+1, nameTa:s.nameTa, nameAr:s.nameAr, ar:a.ar, ta:a.ta||''}));
}


function setJuzPlayIcon(state){
  /* state: 'play' | 'pause' */
  var btn = document.getElementById('juzPlayBtn');
  var icon = document.getElementById('juzPlayIcon');
  if(!btn || !icon) return;
  if(state === 'pause'){
    icon.src = 'icons/icon-stop.png';
    icon.alt = 'Pause';
    btn.classList.add('playing-state');
    btn.setAttribute('title', 'Pause');
    btn.setAttribute('aria-label', 'Pause');
  } else {
    icon.src = 'icons/icon-heart.png';
    icon.alt = 'Play';
    btn.classList.remove('playing-state');
    btn.setAttribute('title', 'Play');
    btn.setAttribute('aria-label', 'Play');
  }
}

function stopContinuous(){
  contPlaying = false;
  contPaused = false;
  if(currentAudio){ currentAudio.pause(); currentAudio=null; }
  const playBtn = document.getElementById('juzPlayBtn');
  if(playBtn) setJuzPlayIcon('play');
  const surahBtn = document.getElementById('playSurahAllBtn');
  if(surahBtn) surahBtn.textContent = _('msg_listen_surah');
  document.querySelectorAll('.juz-surah-card').forEach(el=>el.classList.remove('playing'));
}

function renderAyahPanel(){
  const panel = document.getElementById('juzAyahPanel');
  if(!panel) return;
  // Full-juz mode: show entire contQueue (start ayah → end ayah)
  const useQueue = window.__juzFullMode && contQueue && contQueue.length;
  if(!contQueue.length){
    panel.classList.remove('show');
    panel.innerHTML = '';
    panel.dataset.sid = '';
    return;
  }
  if(!useQueue && !contActiveAyat){
    panel.classList.remove('show');
    panel.innerHTML = '';
    panel.dataset.sid = '';
    return;
  }
  panel.classList.add('show');
  panel.style.display = 'block';
  const sid = useQueue ? ('juz-full-'+(window.__juzFullId||'')) : (contActiveSurahId || '');
  if(panel.dataset.sid !== sid){
    panel.dataset.sid = sid;
    panel.innerHTML = '';
    const rows = useQueue ? contQueue : contActiveAyat;
    rows.forEach(function(a,i){
      const row = document.createElement('div');
      row.className = 'juz-ayah-row';
      const arHtml = (typeof tajweedOn !== 'undefined' && tajweedOn && typeof tajweedify==='function')
        ? tajweedify(a.ar||'') : (a.ar||'');
      const label = useQueue
        ? ((a.nameTa||a.nameAr||'') + ' · ஆயத்து ' + a.ayahNum)
        : (_('lbl_ayah') + ' ' + (a.ayahNum || (i+1)));
      row.innerHTML =
        '<div class="juz-ayah-num">'+label+'</div>'+
        '<div class="juz-ayah-ar">'+arHtml+'</div>'+
        (a.ta ? '<div class="juz-ayah-ta">'+a.ta+'</div>' : '');
      row.onclick = function(){ playContinuousAt(i); };
      panel.appendChild(row);
    });
  }
  panel.querySelectorAll('.juz-ayah-row').forEach(function(row,i){
    row.classList.toggle('active', i === contIndex);
  });
  const active = panel.querySelector('.juz-ayah-row.active');
  if(active) active.scrollIntoView({block:'nearest', behavior:'smooth'});
}

function updateJuzUI(){
  const now = document.getElementById('juzNowPlaying');
  const fill = document.getElementById('juzProgressFill');
  const info = document.getElementById('juzTrackInfo');
  const bar = document.getElementById('juzPlayerBar');
  if(contQueue.length && bar) bar.style.display = '';
  if(!contQueue.length){
    if(now) now.textContent = _('msg_tap_surah_listen');
    if(fill) fill.style.width = '0%';
    if(info) info.textContent = '—';
    renderAyahPanel();
    return;
  }
  const cur = contQueue[contIndex] || contQueue[0];
  if(now) now.textContent = (cur.nameTa||cur.nameAr||'') + ' · ஆயத்து ' + cur.ayahNum;
  if(fill) fill.style.width = ((contIndex+1)/contQueue.length*100) + '%';
  if(info) info.textContent = _('lbl_ayah') + ' ' + (contIndex+1) + ' / ' + contQueue.length;
  document.querySelectorAll('.juz-surah-card').forEach(el=>{
    el.classList.toggle('playing', el.dataset.sid === contActiveSurahId && contPlaying);
  });
  renderAyahPanel();
}

function playContinuousAt(idx){
  if(!contQueue.length) return;
  contIndex = Math.max(0, Math.min(idx, contQueue.length-1));
  contPlaying = true;
  contPaused = false;
  if(currentAudio){ currentAudio.pause(); currentAudio=null; }
  const item = contQueue[contIndex];
  contActiveSurahId = item.id;
  const s = String(item.surahNum).padStart(3,'0');
  const a = String(item.ayahNum).padStart(3,'0');
  const url = 'https://everyayah.com/data/Alafasy_128kbps/'+s+a+'.mp3';
  const audio = new Audio(url);
  currentAudio = audio;
  updateJuzUI();
  const playBtn = document.getElementById('juzPlayBtn');
  if(playBtn) setJuzPlayIcon('pause');
  const surahBtn = document.getElementById('playSurahAllBtn');
  if(surahBtn && currentSurah && contQueue[0] && contQueue[0].id===currentSurah){
    surahBtn.textContent = _('msg_pause');
  }
  audio.play().catch(function(){
    alert(_('msg_audio_fail'));
    stopContinuous();
    updateJuzUI();
  });
  audio.onended = function(){
    if(!contPlaying) return;
    if(contIndex < contQueue.length-1){
      playContinuousAt(contIndex+1);
    } else {
      stopContinuous();
      updateJuzUI();
      if(document.getElementById('juzNowPlaying')) document.getElementById('juzNowPlaying').textContent = '✅ '+(item.nameTa||'')+' முடிந்தது';
    }
  };
}

function toggleContinuousPlay(){
  if(!contQueue.length) return;
  if(contPlaying && !contPaused){
    if(currentAudio) currentAudio.pause();
    contPaused = true;
    contPlaying = false;
    const playBtn = document.getElementById('juzPlayBtn');
    if(playBtn) setJuzPlayIcon('play');
    document.querySelectorAll('.juz-surah-card').forEach(el=>el.classList.remove('playing'));
  } else if(contPaused && currentAudio){
    currentAudio.play();
    contPaused = false;
    contPlaying = true;
    const playBtn = document.getElementById('juzPlayBtn');
    if(playBtn) setJuzPlayIcon('pause');
    updateJuzUI();
  } else {
    playContinuousAt(contIndex);
  }
}

function playSurahFromJuzObj(s){
  stopContinuous();
  contQueue = buildSurahQueueFromObj(s);
  contIndex = 0;
  contActiveSurahId = s.id || ('s'+s.surahNum);
  contActiveAyat = s.ayat.map((a,i)=>({ar:a.ar, ta:a.ta||'', ayahNum:i+1}));
  if(!contQueue.length){ alert(_('msg_no_audio')); return; }
  const bar = document.getElementById('juzPlayerBar');
  if(bar) bar.style.display = '';
  playContinuousAt(0);
}

function playSurahFromJuz(surahId){
  const s = QURAN_DATA[surahId];
  if(!s) return;
  playSurahFromJuzObj({id:surahId, surahNum:s.surahNum, nameAr:s.nameAr, nameTa:s.nameTa, ayat:s.ayat});
}

async function fetchJuzData(juzNum){
  var cacheKey = juzNum + '_' + (typeof currentScript !== 'undefined' ? currentScript : 'indopak');
  if(JUZ_CACHE[cacheKey]) return JUZ_CACHE[cacheKey];

  // Prefer local QURAN_DATA for any juz when we already have those surahs loaded
  var localSurahs = [];
  try {
    var nums = (typeof getSurahNumsForJuz === 'function') ? getSurahNumsForJuz(juzNum) : null;
    if(nums && nums.length && typeof SURAH_META !== 'undefined'){
      var allLocal = true;
      var built = [];
      for(var i=0;i<nums.length;i++){
        var n = nums[i];
        var id = (typeof surahIdForNum === 'function') ? surahIdForNum(n) : ('s'+n);
        var s = QURAN_DATA[id];
        if(!s || !s.ayat || !s.ayat.length){ allLocal = false; break; }
        built.push({
          id: id,
          surahNum: s.surahNum || n,
          nameAr: s.nameAr || '',
          nameEn: '',
          nameTa: s.nameTa || (n+''),
          ayat: s.ayat.map(function(a){ return {ar: a.ar||'', ta: a.ta||''}; })
        });
      }
      if(allLocal && built.length){
        JUZ_CACHE[cacheKey] = {surahs: built};
        return JUZ_CACHE[cacheKey];
      }
    }
  } catch(e){}

  // Fetch correct script from Quran.com API (by juz)
  var isUth = (typeof currentScript !== 'undefined' && currentScript === 'uthmani');
  var edition = isUth ? 'uthmani' : 'indopak';
  var field = isUth ? 'text_uthmani' : 'text_indopak';
  var url = 'https://api.quran.com/api/v4/quran/verses/' + edition + '?juz_number=' + juzNum;

  try {
    var arRes = await fetch(url);
    if(!arRes.ok) throw new Error('API ' + arRes.status);
    var arData = await arRes.json();
    var verses = arData.verses || [];
    if(!verses.length) throw new Error('empty juz');

    // verse_key like "78:1"
    var bySurah = {};
    verses.forEach(function(v){
      var key = String(v.verse_key || '');
      var parts = key.split(':');
      var sn = parseInt(parts[0], 10);
      var an = parseInt(parts[1], 10);
      if(!sn) return;
      if(!bySurah[sn]){
        var meta = (typeof SURAH_META !== 'undefined') ? SURAH_META.find(function(m){ return m.n === sn; }) : null;
        bySurah[sn] = {
          id: (sn === 1 ? 'fatiha' : 's'+sn),
          surahNum: sn,
          nameAr: (meta && meta.ar) || '',
          nameEn: (meta && meta.en) || '',
          nameTa: sn + '. ' + ((meta && meta.en) || ''),
          ayat: []
        };
      }
      var raw = String(v[field] || v.text_uthmani || v.text_indopak || '').replace(/^\uFEFF/,'').trim();
      // First ayah of surah: strip bismillah except Fatiha & Tawbah
      if(an === 1){
        raw = stripBismillah(raw, sn);
      }
      bySurah[sn].ayat.push({ar: raw, ta: ''});
    });

    var surahs = Object.keys(bySurah).map(Number).sort(function(a,b){ return a-b; }).map(function(n){ return bySurah[n]; });
    // Note: Juz may contain PARTIAL surahs — do not overwrite full garden data with partial slices.
    // Only fill QURAN_DATA when we clearly have a complete surah (matches SURAH_META ayah count).
    surahs.forEach(function(s){
      var meta = (typeof SURAH_META !== 'undefined') ? SURAH_META.find(function(m){ return m.n === s.surahNum; }) : null;
      var expected = meta && meta.a ? meta.a : 0;
      var complete = expected > 0 && s.ayat.length === expected;
      if(complete){
        if(!QURAN_DATA[s.id] || !QURAN_DATA[s.id].ayat || QURAN_DATA[s.id].ayat.length !== expected){
          QURAN_DATA[s.id] = {
            nameAr: s.nameAr,
            nameTa: s.nameTa,
            surahNum: s.surahNum,
            ayat: s.ayat.slice()
          };
          if(!state.gardens[s.id] || state.gardens[s.id].planted.length !== expected){
            state.gardens[s.id] = {planted: Array(expected).fill(false)};
          }
        } else {
          for(var i=0;i<s.ayat.length;i++){
            QURAN_DATA[s.id].ayat[i].ar = s.ayat[i].ar;
          }
        }
        try{ saveData(); saveGame(); }catch(e){}
      }
    });

    JUZ_CACHE[cacheKey] = {surahs: surahs};
    return JUZ_CACHE[cacheKey];
  } catch(err){
    console.warn('Juz fetch failed, trying chapter-by-chapter', err);
    // Fallback: load each surah via ensureSurahLoaded
    var nums2 = (typeof getSurahNumsForJuz === 'function') ? getSurahNumsForJuz(juzNum) : null;
    if(!nums2 || !nums2.length) throw err;
    var built2 = [];
    for(var j=0;j<nums2.length;j++){
      var nn = nums2[j];
      var id2 = null;
      if(typeof ensureSurahLoaded === 'function'){
        id2 = await ensureSurahLoaded(nn);
      }
      if(!id2) id2 = (typeof surahIdForNum === 'function') ? surahIdForNum(nn) : ('s'+nn);
      var ss = QURAN_DATA[id2];
      if(ss && ss.ayat && ss.ayat.length){
        built2.push({
          id: id2,
          surahNum: ss.surahNum || nn,
          nameAr: ss.nameAr || '',
          nameEn: '',
          nameTa: ss.nameTa || '',
          ayat: ss.ayat.map(function(a){ return {ar: a.ar||'', ta: a.ta||''}; })
        });
      }
    }
    if(!built2.length) throw err;
    JUZ_CACHE[cacheKey] = {surahs: built2};
    return JUZ_CACHE[cacheKey];
  }
}

