/* ===== Premium Leaderboard (சாதனைகள்) ===== */
var selectedLbLevel = 1;

var selectedLbFilter = 'all';
var selectedLbLevel = 1;

function renderPremiumLeaderboard(){
  ensureLevelMeta();
  checkLevelCompletions();
  var tabs = document.getElementById('lbLevelTabs');
  var podium = document.getElementById('lbPodium');
  var list = document.getElementById('lbList');
  var you = document.getElementById('lbYou');
  var filters = document.getElementById('lbFilters');
  if(!podium || !list) return;

  // filters
  if(filters){
    filters.querySelectorAll('.plb-filter').forEach(function(btn){
      btn.classList.toggle('active', btn.getAttribute('data-filter') === selectedLbFilter);
      btn.onclick = function(){
        selectedLbFilter = btn.getAttribute('data-filter');
        renderPremiumLeaderboard();
      };
    });
  }

  // level tabs
  if(tabs){
    var th = '';
    for(var lv = 1; lv <= SURAH_LEVEL_COUNT; lv++){
      var st = levelStats(lv);
      var cls = 'plb-lv' + (lv === selectedLbLevel ? ' active' : '') + (st.complete ? ' done' : '');
      th += '<button type="button" class="' + cls + '" data-lbl="' + lv + '">L' + lv + '</button>';
    }
    tabs.innerHTML = th;
    tabs.querySelectorAll('[data-lbl]').forEach(function(btn){
      btn.onclick = function(){
        selectedLbLevel = parseInt(btn.getAttribute('data-lbl'), 10);
        renderPremiumLeaderboard();
      };
    });
  }

  var now = Date.now();
  var dayMs = 86400000;
  var entries = (meta.leaderboard || []).filter(function(e){
    if(e.level !== selectedLbLevel) return false;
    if(selectedLbFilter === 'daily') return (now - (e.at||0)) < dayMs;
    if(selectedLbFilter === 'weekly') return (now - (e.at||0)) < dayMs * 7;
    return true;
  });
  entries.sort(function(a,b){ return (a.at||0) - (b.at||0); });

  function av(name, frame){
    var letter = ((name||'வ').trim().charAt(0) || 'வ').toUpperCase();
    return '<div class="plb-av plb-av-' + frame + '"><span>' + letter + '</span></div>';
  }

  // Podium 2 | 1 | 3
  var slots = [
    { place: 2, e: entries[1], frame: 'silver', medal: '🥈' },
    { place: 1, e: entries[0], frame: 'gold', medal: '🥇' },
    { place: 3, e: entries[2], frame: 'bronze', medal: '🥉' }
  ];
  var ph = '';
  var rankIcons = {1:'icons/rank1.png', 2:'icons/rank2.png', 3:'icons/rank3.png'};
  slots.forEach(function(s){
    var name = s.e ? (s.e.name || 'வீரர்') : '—';
    var rank = s.e ? (RANK_LABEL[s.e.rank] || '') : '';
    var icon = rankIcons[s.place] || 'icons/rank1.png';
    ph += '<div class="plb-pod plb-pod-' + s.frame + (s.e ? '' : ' empty') + '">' +
      '<div class="plb-pod-top">' +
        '<img src="' + icon + '" alt="' + s.place + '" class="plb-rank-badge' + (s.place===1?' plb-rank-badge-1':'') + '">' +
        '<div class="plb-pod-name">' + name + '</div>' +
        '<div class="plb-pod-rank">' + rank + '</div>' +
      '</div>' +
      '<div class="plb-pod-base">' +
        '<div class="plb-pod-num">' + s.place + '</div>' +
        '<div class="plb-pod-xp">⭐ ' + (s.e ? (s.e.stars||0) : '—') + '</div>' +
      '</div>' +
    '</div>';
  });
  podium.innerHTML = ph;

  // List (all including top3 for full list, or skip top3)
  if(!entries.length){
    list.innerHTML = '<div class="plb-empty">'+_('msg_lb_empty')+'</div>';
  } else {
    var lh = '';
    entries.forEach(function(e, i){
      var place = i + 1;
      var pad = place < 10 ? '0' + place : '' + place;
      lh += '<div class="plb-row">' +
        '<div class="plb-row-rank">' + pad + '</div>' +
        av(e.name, place===1?'gold':place===2?'silver':place===3?'bronze':'default') +
        '<div class="plb-row-info">' +
          '<div class="plb-row-name">' + (e.name||'வீரர்') + '</div>' +
          '<div class="plb-row-meta">Level ' + e.level + ' · ' + (RANK_LABEL[e.rank]||'') + '</div>' +
        '</div>' +
        '<div class="plb-row-xp"><span>⭐</span> ' + (e.stars||0) + '</div>' +
      '</div>';
    });
    list.innerHTML = lh;
  }

  // Current user card
  if(you){
    var myName = meta.playerName || 'வீரர்';
    var myEntry = null;
    var myPlace = '—';
    for(var i=0;i<entries.length;i++){
      if((entries[i].name||'') === myName){ myEntry = entries[i]; myPlace = i+1; break; }
    }
    // overall progress approx
    var totalDone = 0, totalStars = 0;
    for(var lv=1; lv<=SURAH_LEVEL_COUNT; lv++){
      var st = levelStats(lv);
      totalDone += st.done;
      totalStars += st.stars;
    }
    you.innerHTML =
      '<div class="plb-you-label">நீங்கள்</div>' +
      '<div class="plb-you-rank">#' + myPlace + '</div>' +
      av(myName, 'gold') +
      '<div class="plb-you-info">' +
        '<div class="plb-you-name">' + myName + '</div>' +
        '<div class="plb-you-meta">'+_('lbl_surah')+' ' + totalDone + '/114 · ⭐ ' + totalStars + '</div>' +
      '</div>' +
      '<div class="plb-you-arrow">↑</div>';
  }
}


