/* ===== Dhikr sound effects ===== */
const DhikrSFX = {
  enabled: true,
  _ctx: null,
  init: function(){
    if(!this._ctx){
      try{ this._ctx = new (window.AudioContext||window.webkitAudioContext)(); }catch(e){}
    }
    if(this._ctx && this._ctx.state === 'suspended') this._ctx.resume();
  },
  _tone: function(freq, dur, type, vol, slide){
    if(!this.enabled) return;
    if(typeof AudioFX !== 'undefined' && AudioFX.enabled === false) return;
    try{
      this.init();
      if(!this._ctx) return;
      const t = this._ctx.currentTime;
      const o = this._ctx.createOscillator();
      const g = this._ctx.createGain();
      o.type = type || 'sine';
      o.frequency.setValueAtTime(freq, t);
      if(slide) o.frequency.exponentialRampToValueAtTime(Math.max(80, slide), t + dur);
      g.gain.setValueAtTime(vol || 0.08, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + dur);
      o.connect(g); g.connect(this._ctx.destination);
      o.start(t); o.stop(t + dur + 0.02);
    }catch(e){}
  },
  click: function(){
    // soft bead-like tick
    this._tone(920, 0.06, 'sine', 0.07);
    this._tone(620, 0.08, 'triangle', 0.04);
  },
  milestone: function(){
    // short pleasant chime (every 33 / target)
    this._tone(523, 0.12, 'sine', 0.09, 780);
    setTimeout(()=>{ this._tone(659, 0.14, 'sine', 0.08); }, 80);
  },
  complete: function(){
    this._tone(523, 0.15, 'sine', 0.1, 660);
    setTimeout(()=>{ this._tone(659, 0.15, 'sine', 0.09, 784); }, 100);
    setTimeout(()=>{ this._tone(784, 0.2, 'sine', 0.08); }, 220);
  }
};
function playClick(){ DhikrSFX.click(); }
function playSuccess(){ DhikrSFX.complete(); }


