/* ===== SAFE TAJWEED (context only – options stay plain) ===== */
/* ===== QCF V4 Tajweed (page fonts + code_v2 glyphs) ===== */
const QCF_FACE_CACHE = {};
const QCF_VERSE_CACHE = {};
let qcfEnabled = false;

function injectQcfFontFace(fam, url){
  const id = 'ff-' + fam;
  if(document.getElementById(id)) return;
  const style = document.createElement('style');
  style.id = id;
  style.textContent = "@font-face{font-family:'" + fam + "';src:url('" + url + "') format('woff2');font-display:swap;}";
  document.head.appendChild(style);
}

function loadQcfV4Font(page){
  const fam = 'QCF4V_p' + page;
  if(QCF_FACE_CACHE[fam] === 'ready') return Promise.resolve(fam);
  if(QCF_FACE_CACHE[fam] && QCF_FACE_CACHE[fam].then) return QCF_FACE_CACHE[fam];

  const urlColr = 'https://verses.quran.foundation/fonts/quran/hafs/v4/colrv1/woff2/p' + page + '.woff2';
  const urlSvg = 'https://verses.quran.foundation/fonts/quran/hafs/v4/ot-svg/dark/woff2/p' + page + '.woff2';

  QCF_FACE_CACHE[fam] = new Promise(function(resolve, reject){
    // Prefer FontFace API; also inject @font-face for Android WebView
    injectQcfFontFace(fam, urlColr);
    if(typeof FontFace === 'undefined'){
      // wait a bit for CSS font download
      setTimeout(function(){ QCF_FACE_CACHE[fam] = 'ready'; resolve(fam); }, 800);
      return;
    }
    const face = new FontFace(fam, 'url(' + urlColr + ')', { display: 'swap' });
    face.load().then(function(f){
      document.fonts.add(f);
      QCF_FACE_CACHE[fam] = 'ready';
      resolve(fam);
    }).catch(function(){
      injectQcfFontFace(fam + '_svg', urlSvg);
      const face2 = new FontFace(fam, 'url(' + urlSvg + ')', { display: 'swap' });
      return face2.load().then(function(f){
        document.fonts.add(f);
        QCF_FACE_CACHE[fam] = 'ready';
        resolve(fam);
      });
    }).catch(function(err){
      QCF_FACE_CACHE[fam] = null;
      reject(err);
    });
  });
  return QCF_FACE_CACHE[fam];
}

async function getQcfVerse(surahNum, ayahNum){
  const key = surahNum + ':' + ayahNum;
  if(QCF_VERSE_CACHE[key]) return QCF_VERSE_CACHE[key];
  try{
    const res = await fetch('https://api.quran.com/api/v4/quran/verses/code_v2?verse_key=' + encodeURIComponent(key));
    if(!res.ok) throw new Error('fail');
    const data = await res.json();
    const v = (data.verses && data.verses[0]) || null;
    if(!v || !v.code_v2) throw new Error('no verse');
    const out = { code: v.code_v2, page: v.v2_page };
    QCF_VERSE_CACHE[key] = out;
    return out;
  }catch(e){
    return null;
  }
}

function renderUnicodeAyah(el, arabic, meaning){
  el.classList.remove('qcf-ayah', 'loading');
  el.style.fontFamily = '';
  el.innerHTML = '';
  if(tajweedOn) el.innerHTML = tajweedify(arabic||'');
  else el.textContent = arabic||'';
  if(showMeaning && meaning){
    const md = document.createElement('div');
    md.className = 'ta-meaning';
    md.textContent = meaning;
    el.appendChild(md);
  }
}

async function renderQcfInto(el, surahNum, ayahNum, fallbackArabic, meaning){
  el.classList.add('loading');
  el.classList.remove('qcf-ayah');
  el.innerHTML = '<span style="font-size:14px;color:#8899aa">⏳ QCF font...</span>';
  try{
    if(!qcfEnabled || !surahNum || !ayahNum){
      renderUnicodeAyah(el, fallbackArabic, meaning);
      return;
    }
    const v = await getQcfVerse(surahNum, ayahNum);
    if(!v || !v.code || !v.page){
      renderUnicodeAyah(el, fallbackArabic, meaning);
      return;
    }
    let fam;
    try {
      fam = await loadQcfV4Font(v.page);
    } catch(e){
      renderUnicodeAyah(el, fallbackArabic, meaning);
      return;
    }
    // CRITICAL: only set QCF codes with the QCF font — never fallback fonts
    // (fallback fonts show circles/boxes for Private Use glyphs)
    el.classList.remove('loading');
    el.classList.add('qcf-ayah');
    el.style.fontFamily = "'" + fam + "'";
    el.textContent = v.code;
    if(showMeaning && meaning){
      const md = document.createElement('div');
      md.className = 'ta-meaning';
      md.textContent = meaning;
      el.appendChild(md);
    }
  }catch(e){
    renderUnicodeAyah(el, fallbackArabic, meaning);
  }
}

let tajweedOn = true;
// showMeaning already declared above

/* Harakat + ALL Uthmani annotation marks must stay attached to base letter */
const TW_HARAKAT = /[\u064B-\u065F\u0670\u06D6-\u06ED\u08F0-\u08FF\u0640]/;
const TW_QALQALAH = new Set(['ق','ط','ب','ج','د']);
const TW_GHUNNAH = new Set(['ن','م']);
const TW_IDGHAM_G = new Set(['ي','ن','م','و']);
const TW_IDGHAM_NG = new Set(['ل','ر']);
const TW_IQLAB = new Set(['ب']);
const TW_HAMZA = new Set(['ء','أ','إ','ئ','ؤ','آ']);
const TW_IZHAR = new Set(['ه','ع','ح','غ','خ']);
const TW_ALIF = new Set(['ا','آ','ٱ','ى']);

function tajweedify(text){
  if(!tajweedOn || !text) return text;
  try {
    const chars = Array.from(text);
    const clusters = [];
    for(const ch of chars){
      if(TW_HARAKAT.test(ch) && clusters.length) clusters[clusters.length-1].marks += ch;
      else clusters.push({base:ch, marks:''});
    }
    function nextLetter(i){
      let j=i+1, crossed=false;
      while(j<clusters.length && (clusters[j].base===' ' || clusters[j].base==='\u200c')){ crossed=true; j++; }
      if(j>=clusters.length) return null;
      return {cluster:clusters[j], index:j, crossedWord:crossed};
    }
    function prevLetter(i){
      let j=i-1;
      while(j>=0 && clusters[j].base===' ') j--;
      return j>=0 ? clusters[j] : null;
    }
    const tokens = [];
    for(let i=0;i<clusters.length;i++){
      const c = clusters[i];
      const prev = prevLetter(i);
      const hasShadda = c.marks.includes('\u0651');
      const hasSukun = c.marks.includes('\u0652');
      const hasTanween = /[\u064B\u064C\u064D]/.test(c.marks);
      const hasDagger = c.marks.includes('\u0670');
      const hasMaddah = c.marks.includes('\u0653');
      let cls = null;

      if(TW_GHUNNAH.has(c.base) && hasShadda) cls = 'tw-ghunnah';
      else if(TW_QALQALAH.has(c.base) && hasSukun) cls = 'tw-qalqalah';
      else if((c.base==='ن' && hasSukun) || hasTanween){
        let nxt = nextLetter(i);
        if(nxt && !nxt.crossedWord && c.marks.includes('\u064B') && TW_ALIF.has(nxt.cluster.base) && nxt.cluster.marks===''){
          nxt = nextLetter(nxt.index);
        }
        if(nxt){
          const nb = nxt.cluster.base;
          const sameYW = !nxt.crossedWord && (nb==='ي'||nb==='و');
          if(sameYW || TW_HAMZA.has(nb) || TW_IZHAR.has(nb)) cls = null;
          else if(TW_IDGHAM_G.has(nb)) cls = 'tw-ghunnah';
          else if(TW_IDGHAM_NG.has(nb)) cls = 'tw-idgham';
          else if(TW_IQLAB.has(nb)) cls = 'tw-iqlab';
          else cls = 'tw-ikhfa';
        }
      } else {
        let isMadd = false;
        let forceLong = hasMaddah;

        if(hasDagger) isMadd = true;
        if(c.base === 'آ'){ isMadd = true; forceLong = true; }
        if(TW_ALIF.has(c.base) && prev && prev.marks.includes('\u064E')) isMadd = true;
        if(c.base === 'و' && (c.marks === '' || hasSukun) && prev && prev.marks.includes('\u064F')) isMadd = true;
        if((c.base === 'ي' || c.base === 'ى') && (c.marks === '' || hasSukun) && prev && prev.marks.includes('\u0650')) isMadd = true;
        if(hasMaddah && (TW_ALIF.has(c.base) || c.base==='و' || c.base==='ي')){ isMadd = true; forceLong = true; }

        if(isMadd){
          const nxt = nextLetter(i);
          const beforeHamza = nxt && TW_HAMZA.has(nxt.cluster.base);
          const beforeShadda = nxt && !nxt.crossedWord && nxt.cluster.marks.includes('\u0651');
          if(forceLong || beforeHamza || beforeShadda) cls = 'tw-madd-long';
          else cls = 'tw-madd';
        }
      }

      if(!cls && hasShadda) cls = 'tw-shadda';
      tokens.push({text: c.base + c.marks, cls: cls});
    }
    return tokens.map(t => t.cls ? ('<span class="'+t.cls+'">'+t.text+'</span>') : t.text).join('');
  } catch(e){
    return text;
  }
}


function setContextText(el, arabic, meaning, surahNum, ayahNum){
  el.classList.remove('qcf-ayah');
  el.style.fontFamily = '';
  // Prefer QCF V4 when we have verse coordinates and QCF is enabled
  if(qcfEnabled && surahNum && ayahNum){
    renderQcfInto(el, surahNum, ayahNum, arabic, meaning);
    return;
  }
  el.innerHTML = '';
  if(tajweedOn){
    el.innerHTML = tajweedify(arabic||'');
  } else {
    el.textContent = arabic||'';
  }
  if(showMeaning && meaning){
    const md = document.createElement('div');
    md.className = 'ta-meaning';
    md.textContent = meaning;
    el.appendChild(md);
  }
}

