/* Android back / edge-swipe / in-app swipe — ONE step only */
(function(){
  if(window.GAME_SWIPE_BOUND) return;
  window.GAME_SWIPE_BOUND = true;

  var sx = 0, sy = 0, st = 0, tracking = false;
  var MIN_DX = 80;
  var MAX_DY = 70;
  var MAX_MS = 700;
  var lastBackAt = 0;

  function onGamesScreen(){
    var scr = document.getElementById('screenGames');
    return !!(scr && scr.classList.contains('active'));
  }

  function oneStepBack(){
    var now = Date.now();
    if(now - lastBackAt < 500) return; // hard debounce
    lastBackAt = now;
    if(!onGamesScreen()) return;
    if(typeof Games !== 'undefined' && Games.goBack) Games.goBack();
  }

  // In-app swipe right
  document.addEventListener('touchstart', function(e){
    if(!onGamesScreen()){ tracking = false; return; }
    if(!e.touches || e.touches.length !== 1) return;
    var t = e.touches[0];
    sx = t.clientX; sy = t.clientY; st = Date.now();
    tracking = true;
  }, {passive:true});

  document.addEventListener('touchend', function(e){
    if(!tracking) return;
    tracking = false;
    if(!onGamesScreen()) return;
    if(!e.changedTouches || !e.changedTouches[0]) return;
    var t = e.changedTouches[0];
    var dx = t.clientX - sx;
    var dy = Math.abs(t.clientY - sy);
    var dt = Date.now() - st;
    if(dx > MIN_DX && dy < MAX_DY && dt < MAX_MS){
      oneStepBack();
    }
  }, {passive:true});

  // Android Chrome edge-swipe / system back uses history
  window.addEventListener('popstate', function(ev){
    if(!onGamesScreen()) return;
    // intercept: do one in-app step instead of leaving page
    var play = document.getElementById('gamePlayArea');
    var playing = play && play.style.display === 'block';
    if(playing){
      // stay in app — show menu
      if(typeof Games !== 'undefined') Games.showMenu();
      try{ history.pushState({qg:'games-menu'}, ''); }catch(e){}
    } else {
      // on menu — go garden once
      if(typeof switchScreen === 'function') switchScreen('screenSelect');
      try{ history.pushState({qg:'home'}, ''); }catch(e){}
    }
  });

  // When user opens Games screen, plant a history entry
  var _origSwitch = null;
  function hookSwitch(){
    if(typeof switchScreen !== 'function' || switchScreen.__gameHistHooked) return;
    _origSwitch = switchScreen;
    switchScreen = function(id){
      var r = _origSwitch.apply(this, arguments);
      try{
        if(id === 'screenGames'){
          history.pushState({qg:'games-menu'}, '');
        }
      }catch(e){}
      return r;
    };
    switchScreen.__gameHistHooked = true;
    if(_origSwitch.__sfxWrapped) switchScreen.__sfxWrapped = true;
  }
  if(document.readyState === 'loading'){
    
// Auto-save full progress when leaving / hiding tab
try{
  window.addEventListener('beforeunload', function(){ try{ saveAllProgress(); }catch(e){} });
  document.addEventListener('visibilitychange', function(){
    if(document.visibilityState === 'hidden'){ try{ saveAllProgress(); }catch(e){} }
  });
}catch(e){}

document.addEventListener('DOMContentLoaded', hookSwitch);
  } else {
    setTimeout(hookSwitch, 0);
  }
})();






