/* ===== Arabic display font picker (app-wide) ===== */
const AR_FONT_KEY = 'quran_ar_font_v2';
const AR_FONT_FILES = {
  Lateef: 'fonts/Lateef.ttf',
  Marhey: 'fonts/Marhey.ttf',
  ScheherazadeNew: 'fonts/ScheherazadeNew.ttf',
  NotoNaskhArabic: 'fonts/NotoNaskhArabic.ttf',
  Vazirmatn: 'fonts/Vazirmatn.ttf'
};
const AR_FONT_STACK = {
  default: null,
  Lateef: "'Lateef','Noto Naskh Arabic',serif",
  Marhey: "'Marhey','Noto Naskh Arabic',serif",
  ScheherazadeNew: "'ScheherazadeNew','Scheherazade New',serif",
  NotoNaskhArabic: "'NotoNaskhArabic','Noto Naskh Arabic',serif",
  Vazirmatn: "'Vazirmatn','Noto Naskh Arabic',sans-serif"
};
const AR_FONT_LABELS = {
  default: 'இயல்பு (Default)',
  Lateef: 'Lateef', Marhey: 'Marhey',
  ScheherazadeNew: 'Scheherazade', NotoNaskhArabic: 'Noto Naskh', Vazirmatn: 'Vazirmatn'
};
let currentArFont = 'default';
var __arFontsLoaded = {};

function loadArFontFile(key){
  if(!key || key==='default' || __arFontsLoaded[key]) return Promise.resolve();
  var path = AR_FONT_FILES[key];
  if(!path) return Promise.resolve();
  if(typeof FontFace === 'undefined'){
    __arFontsLoaded[key] = true;
    return Promise.resolve();
  }
  try{
    var ff = new FontFace(key, 'url(' + path + ')');
    return ff.load().then(function(loaded){
      document.fonts.add(loaded);
      __arFontsLoaded[key] = true;
    }).catch(function(){
      var ff2 = new FontFace(key, "url('./" + path + "')");
      return ff2.load().then(function(loaded){
        document.fonts.add(loaded);
        __arFontsLoaded[key] = true;
      }).catch(function(){ __arFontsLoaded[key] = true; });
    });
  }catch(e){
    __arFontsLoaded[key] = true;
    return Promise.resolve();
  }
}

function applyArabicFont(id){
  var key = (id && (id in AR_FONT_STACK)) ? id : 'default';
  currentArFont = key;
  var stack = AR_FONT_STACK[key];
  function paint(){
    try{
      var b = document.body;
      if(b){
        (b.className || '').split(/\s+/).forEach(function(cl){
          if(cl.indexOf('ar-font-') === 0) b.classList.remove(cl);
        });
        if(key && key !== 'default') b.classList.add('ar-font-' + key);
      }
    }catch(e){}
    if(stack){
      document.documentElement.style.setProperty('--font-ar', stack);
      document.documentElement.style.setProperty('--font-ar-display', stack);
    } else {
      document.documentElement.style.removeProperty('--font-ar-display');
      try{ if(typeof applyScriptFonts==='function') applyScriptFonts(); }catch(e){}
    }
    try{ localStorage.setItem(AR_FONT_KEY, key); }catch(e){}
    document.querySelectorAll('.ar-font-btn').forEach(function(btn){
      btn.classList.toggle('active', btn.getAttribute('data-arfont') === key);
    });
    var lab = document.getElementById('arFontLabel');
    if(lab) lab.textContent = AR_FONT_LABELS[key] || key;
  }
  if(key !== 'default'){
    loadArFontFile(key).then(paint).catch(paint);
  } else {
    paint();
  }
}

function initArabicFontSelector(){
  Object.keys(AR_FONT_FILES).forEach(function(k){ loadArFontFile(k); });
  var saved = 'default';
  try{ saved = localStorage.getItem(AR_FONT_KEY) || 'default'; }catch(e){}
  applyArabicFont(saved);
  document.querySelectorAll('.ar-font-btn').forEach(function(btn){
    btn.onclick = function(){ applyArabicFont(btn.getAttribute('data-arfont')); };
  });
}

function updateArabicFontUI(){
  applyArabicFont(currentArFont);
}





