/* App splash — Bismillah qira'at ONLY on open (not on other clicks) */
(function(){
  function tryPlayBismillahOnce(){
    if(window.__bismillahPlayed || window.__bismillahPlaying) return;
    try{
      if(typeof AudioFX === 'undefined') return;
      if(AudioFX.init) AudioFX.init();
      AudioFX.playBismillah();
    }catch(e){}
  }
  function hideSplash(){
    var el = document.getElementById('appSplash');
    if(!el) return;
    el.classList.add('hide');
    // mark done so later taps never retrigger Bismillah
    window.__bismillahPlayed = true;
    setTimeout(function(){
      try{ if(typeof AudioFX!=='undefined' && AudioFX.stopBismillah) AudioFX.stopBismillah(); }catch(e){}
      if(el && el.parentNode) el.parentNode.removeChild(el);
    }, 900);
  }
  function startSplash(){
    var el = document.getElementById('appSplash');
    if(!el) return;
    // Play once at open
    tryPlayBismillahOnce();
    // One retry if autoplay was blocked (still only during splash)
    setTimeout(tryPlayBismillahOnce, 400);
    // Mobile: ONLY tapping the splash screen can start qira'at (not menu/icons)
    function splashTap(ev){
      if(window.__bismillahPlayed) return;
      tryPlayBismillahOnce();
    }
    el.addEventListener('click', splashTap, false);
    el.addEventListener('touchstart', splashTap, {passive:true});
    setTimeout(hideSplash, 5500);
  }
  // NO document-level listeners — prevents Bismillah on every icon click
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', startSplash);
  } else {
    startSplash();
  }
})();





/* Global UI sound effects — almost every tap */
(function(){
  if(window.SFX_ALL_BOUND) return;
  window.SFX_ALL_BOUND = true;

  function sfx(name){
    try{
      if(typeof AudioFX === 'undefined' || !AudioFX.enabled) return;
      var fn = AudioFX[name];
      if(typeof fn === 'function') fn.call(AudioFX);
    }catch(e){}
  }

  document.addEventListener('click', function(ev){
    var t = ev.target;
    if(!t || !t.closest) return;

    // Don't double-play on memory cards / options that already fire in game code
    if(t.closest('.memory-card')) return;
    if(t.closest('.opt-btn')) return;
    if(t.closest('.sq-opt')) return;

    if(t.closest('#openMenuBtn') || t.closest('.menu-btn-header')) { sfx('playWhoosh'); return; }
    if(t.closest('.side-nav-item')) { sfx('playNav'); return; }
    if(t.closest('.theme-swatch')) { sfx('playPop'); return; }
    if(t.closest('.game-card')) { sfx('playStart'); return; }
    if(t.closest('.juz-icon-btn') || t.closest('.juz-setting-row')) { sfx('playClick'); return; }
    if(t.closest('.level-tile')) { sfx('playClick'); return; }
    if(t.closest('.back-btn')) { sfx('playSoft'); return; }
    if(t.closest('.submit-btn') || t.closest('.mode-btn') || t.closest('.play-all-btn')) { sfx('playStart'); return; }
    if(t.closest('.dhikr-card') || t.closest('.dhikr-btn') || t.closest('#dhikrTapBtn') || t.closest('.dhikr-tap')) { sfx('playTick'); return; }
    if(t.closest('.dua-card') || t.closest('.nabi-dua-item')) { sfx('playSoft'); return; }
    if(t.closest('.icon-btn') || t.closest('#soundBtn')) { sfx('playToggle'); return; }
    if(t.closest('.ayah-dot') || t.closest('.juz-chip')) { sfx('playTick'); return; }
    if(t.closest('button') || t.closest('[role="button"]')) { sfx('playClick'); return; }
  }, true);

  // Screen switch whoosh
  if(typeof switchScreen === 'function' && !switchScreen.__sfxWrapped){
    var _sw = switchScreen;
    switchScreen = function(id){
      sfx('playWhoosh');
      return _sw.apply(this, arguments);
    };
    switchScreen.__sfxWrapped = true;
  }
})();


/* Unlock WebAudio on first user gesture (mobile) */
(function(){
  if(window.AUDIO_UNLOCK) return;
  window.AUDIO_UNLOCK = true;
  function unlock(){
    try{
      if(typeof AudioFX !== 'undefined'){
        AudioFX.init();
        if(AudioFX.ctx && AudioFX.ctx.state === 'suspended') AudioFX.ctx.resume();
      }
    }catch(e){}
    document.removeEventListener('touchstart', unlock, true);
    document.removeEventListener('click', unlock, true);
  }
  document.addEventListener('touchstart', unlock, true);
  document.addEventListener('click', unlock, true);
})();


