/* ===== மீலாது நிகழ்வு · ஸலவாத் Leaderboard ===== */

function addQuizToMiladBoard(score, total){
  if(total < 100) return;
  ensureMiladMeta();
  var name = meta.playerName || localStorage.getItem('qg_player_name') || 'வீரர்';
  var found = null;
  for(var i=0;i<meta.miladBoard.length;i++){
    if(meta.miladBoard[i].name === name){ found = meta.miladBoard[i]; break; }
  }
  var entry = {
    name: name,
    total: score,
    today: score,
    quizScore: score,
    quizTotal: total,
    type: 'quiz',
    at: Date.now()
  };
  if(found){
    // keep best quiz score
    if(score >= (found.total||0)){
      found.total = score;
      found.today = score;
      found.quizScore = score;
      found.quizTotal = total;
      found.type = 'quiz';
      found.at = Date.now();
    }
  } else {
    meta.miladBoard.push(entry);
  }
  saveMeta();
  try{ if(typeof renderMiladLeaderboard==='function') renderMiladLeaderboard(); }catch(e){}
}
function ensureMiladMeta(){
  if(!meta.milad){
    meta.milad = { total: 0, today: 0, todayDate: null };
  }
  var today = new Date().toISOString().slice(0,10);
  if(meta.milad.todayDate !== today){
    meta.milad.today = 0;
    meta.milad.todayDate = today;
  }
  if(!meta.miladBoard) meta.miladBoard = [];
}
function addMiladSalawat(n){
  if(n <= 0) return;
  ensureMiladMeta();
  meta.milad.total = (meta.milad.total || 0) + n;
  meta.milad.today = (meta.milad.today || 0) + n;
  try{ localStorage.setItem('qg_salawat_count', String(meta.milad.total)); }catch(e){}
  saveMeta();
  // Salawat no longer joins Milad leaderboard (Quiz 100 does)
}
function triggerSalawat1LakhTelegram(playerName, total){
  // removed — 1 lakh salawat milestone deleted
  return;
}

function seedMiladLeaderboard(){
  ensureMiladMeta();
  if(!meta.miladBoard) meta.miladBoard = [];
  // Fixed showcase places (always top)
  var seeds = [
    { name: 'ha_sena123', total: 96, today: 96, quizScore: 96, quizTotal: 100, at: Date.now(), pinned: 1 },
    { name: 'islamic_post_1704', total: 84, today: 84, quizScore: 84, quizTotal: 100, at: Date.now(), pinned: 2 }
  ];
  seeds.forEach(function(s){
    var found = null;
    for(var i=0;i<meta.miladBoard.length;i++){
      if(meta.miladBoard[i].name === s.name){ found = meta.miladBoard[i]; break; }
    }
    if(found){
      found.total = s.total;
      found.today = s.today;
      found.quizScore = s.quizScore;
      found.quizTotal = s.quizTotal;
      found.pinned = s.pinned;
      found.at = found.at || Date.now();
    } else {
      meta.miladBoard.push(s);
    }
  });
  // Sort: pinned first by pin order, then by total
  meta.miladBoard.sort(function(a,b){
    var pa = a.pinned || 99, pb = b.pinned || 99;
    if(pa !== pb) return pa - pb;
    return (b.total||0) - (a.total||0);
  });
  try{ saveMeta(); }catch(e){}
}

function renderMiladLeaderboard(){
  ensureMiladMeta();
  try{ seedMiladLeaderboard(); }catch(e){}
  var filter = (window.__miladLbFilter || 'all');
  var board = (meta.miladBoard || []).slice();
  var now = Date.now();
  var dayMs = 86400000;
  if(filter === 'daily'){
    board = board.filter(function(e){ return (now - (e.at||0)) < dayMs; });
  } else if(filter === 'weekly'){
    board = board.filter(function(e){ return (now - (e.at||0)) < dayMs * 7; });
  }
  board.sort(function(a,b){
    var pa = a.pinned || 99, pb = b.pinned || 99;
    if(pa !== pb) return pa - pb;
    if(filter === 'daily') return (b.today||0) - (a.today||0);
    return (b.total||0) - (a.total||0);
  });

  var podium = document.getElementById('miladLbPodium');
  var list = document.getElementById('miladLbList');
  var you = document.getElementById('miladLbYou');
  var rankIcons = {1:'icons/rank1.png', 2:'icons/rank2.png', 3:'icons/rank3.png'};

  if(podium){
    var slots = [
      { place: 2, e: board[1] },
      { place: 1, e: board[0] },
      { place: 3, e: board[2] }
    ];
    var ph = '';
    slots.forEach(function(s){
      var name = s.e ? (s.e.name || 'வீரர்') : '—';
      var score;
      if(!s.e) score = '—';
      else if(s.e.quizScore != null) score = (s.e.quizScore||0)+'/'+(s.e.quizTotal||100);
      else score = (filter==='daily' ? (s.e.today||0) : (s.e.total||0));
      var firstCls = s.place === 1 ? ' podium-first' : '';
      ph += '<div class="podium-slot'+firstCls+'">'+
        '<img src="'+rankIcons[s.place]+'" alt="'+s.place+'" class="podium-rank-img">'+
        '<div class="podium-name">'+name+'</div>'+
        '<div class="podium-score">📝 '+score+'</div>'+
      '</div>';
    });
    podium.innerHTML = ph;
  }

  if(list){
    if(!board.length){
      list.innerHTML = '<div style="text-align:center;padding:20px;color:var(--text-dim)">'+_('msg_milad_empty')+'</div>';
    } else {
      var lh = '';
      board.forEach(function(e, i){
        var place = i + 1;
        var score = (e.quizScore != null) ? ((e.quizScore||0)+'/'+(e.quizTotal||100)) : (filter==='daily' ? (e.today||0) : (e.total||0));
        lh += '<div class="plb-row">'+
          '<span class="plb-pos">'+place+'</span>'+
          '<span class="plb-name">'+(e.name||'வீரர்')+'</span>'+
          '<span class="plb-pts">📝 '+score+'</span>'+
        '</div>';
      });
      list.innerHTML = lh;
    }
  }

  if(you){
    var myName = meta.playerName || 'வீரர்';
    var myPlace = '—';
    for(var i=0;i<board.length;i++){
      if(board[i].name === myName){ myPlace = i+1; break; }
    }
    var myEntry = null;
    for(var j=0;j<(meta.miladBoard||[]).length;j++){
      if(meta.miladBoard[j].name === myName){ myEntry = meta.miladBoard[j]; break; }
    }
    var myScore = myEntry ? (myEntry.total||0) : 0;
    var metaLine = myEntry
      ? ('கேள்வி & பதில் · '+(myEntry.quizScore||myEntry.total||0)+'/'+(myEntry.quizTotal||100))
      : '100 கேள்வி முடித்தால் இங்கே சேரும்';
    you.innerHTML =
      '<span class="plb-pos">#'+myPlace+'</span>'+
      '<div class="plb-you-avatar">'+(myName.charAt(0)||'வ')+'</div>'+
      '<div class="plb-you-info">'+
        '<div class="plb-you-name">'+myName+'</div>'+
        '<div class="plb-you-meta">'+metaLine+'</div>'+
      '</div>'+
      '<span class="plb-pts">📝 '+myScore+'</span>';
  }
}
function initMilad(){
  ensureMiladMeta();
  try{ seedMiladLeaderboard(); }catch(e){}
  window.__miladLbFilter = window.__miladLbFilter || 'all';
  var filters = document.getElementById('miladLbFilters');
  if(filters){
    filters.querySelectorAll('.plb-filter').forEach(function(btn){
      btn.classList.toggle('active', btn.getAttribute('data-filter') === window.__miladLbFilter);
      btn.onclick = function(){
        window.__miladLbFilter = btn.getAttribute('data-filter');
        filters.querySelectorAll('.plb-filter').forEach(function(b){ b.classList.toggle('active', b===btn); });
        renderMiladLeaderboard();
      };
    });
  }
  renderMiladLeaderboard();
  var btn = document.getElementById('miladBackBtn');
  if(btn){
    btn.onclick = function(){
      if(typeof switchScreen === 'function') switchScreen('screenSelect');
    };
  }
}

function initSalawat(){
  ensureMiladMeta();
  var count = meta.milad.total || 0;
  try{
    var legacy = parseInt(localStorage.getItem('qg_salawat_count')||'0',10)||0;
    if(legacy > count){
      meta.milad.total = legacy;
      count = legacy;
      saveMeta();
    }
  }catch(e){}

  var countEl = document.getElementById('salawatCount');
  var arEl = document.getElementById('salawatMainAr');
  var types = document.getElementById('salawatTypes');
  if(countEl) countEl.textContent = String(count);

  if(types){
    var activeI = 0;
    try{
      var act = types.querySelector('.salawat-type-card.active');
      if(act) activeI = parseInt(act.getAttribute('data-i'),10)||0;
    }catch(e){}
    types.innerHTML = SALAWAT_TYPES.map(function(t, i){
      return '<button type="button" class="salawat-type-card'+(i===activeI?' active':'')+'" data-i="'+i+'">'+
        '<div class="salawat-type-num">'+t.n+'</div>'+
        '<div class="salawat-type-name">'+(isEnLang()?(t.nameEn||t.name):t.name)+'</div>'+
        '<div class="salawat-type-ar">'+t.ar+'</div></button>';
    }).join('');
    if(!types.dataset.bound){
      types.dataset.bound = '1';
      types.onclick = function(ev){
        var card = ev.target.closest('.salawat-type-card');
        if(!card) return;
        var i = parseInt(card.getAttribute('data-i'),10);
        var t = SALAWAT_TYPES[i];
        if(!t) return;
        types.querySelectorAll('.salawat-type-card').forEach(function(c){ c.classList.remove('active'); });
        card.classList.add('active');
        if(arEl) arEl.textContent = t.ar;
        var sub = document.getElementById('salawatMainTa');
        if(sub) sub.textContent = isEnLang() ? (t.nameEn || t.name) : (t.ta || t.name);
        try{ if(typeof AudioFX!=='undefined'&&AudioFX.playClick) AudioFX.playClick(); }catch(e){}
      };
    }
  }

  var tap = document.getElementById('salawatTapBtn');
  if(tap && !tap.dataset.bound){
    tap.dataset.bound = '1';
    tap.onclick = function(){
      addMiladSalawat(1);
      count = meta.milad.total;
      if(countEl) countEl.textContent = String(count);
      try{ if(typeof AudioFX!=='undefined'&&AudioFX.playTick) AudioFX.playTick(); else if(AudioFX&&AudioFX.playClick) AudioFX.playClick(); }catch(e){}
      tap.style.transform = 'scale(0.97)';
      setTimeout(function(){ tap.style.transform = ''; }, 120);
      var h = document.getElementById('miladSalawatHint');
      if(h) h.innerHTML = '💚 ஸலவாத்: இன்று <b>'+(meta.milad.today||0)+'</b> · மொத்தம் <b>'+(meta.milad.total||0)+'</b>';
    };
  }
  var reset = document.getElementById('salawatResetBtn');
  if(reset && !reset.dataset.bound){
    reset.dataset.bound = '1';
    reset.onclick = function(){
      if(!confirm(_('msg_reset_salawat'))) return;
      ensureMiladMeta();
      meta.milad.total = 0;
      meta.milad.today = 0;
      saveMeta();
      try{ localStorage.setItem('qg_salawat_count', '0'); }catch(e){}
      count = 0;
      if(countEl) countEl.textContent = '0';
    };
  }
  var back = document.getElementById('salawatBackBtn');
  if(back) back.onclick = function(){ if(typeof switchScreen==='function') switchScreen('screenSelect'); };

  var card = document.querySelector('.salawat-counter-card');
  if(card && !document.getElementById('miladSalawatHint')){
    var hint = document.createElement('div');
    hint.id = 'miladSalawatHint';
    hint.style.cssText = 'text-align:center;font-size:11px;color:#ffd54f;margin-top:8px;font-weight:700';
    hint.innerHTML = '💚 ஸலவாத்: இன்று <b>'+(meta.milad.today||0)+'</b> · மொத்தம் <b>'+(meta.milad.total||0)+'</b>';
    card.appendChild(hint);
  } else {
    var h2 = document.getElementById('miladSalawatHint');
    if(h2) h2.innerHTML = '💚 ஸலவாத்: இன்று <b>'+(meta.milad.today||0)+'</b> · மொத்தம் <b>'+(meta.milad.total||0)+'</b>';
  }
  var goBtn = document.getElementById('goMiladFromSalawat');
  if(goBtn) goBtn.onclick = function(){ if(typeof switchScreen==='function') switchScreen('screenMilad'); };
}

// hook switchScreen for Salawat + Milad
(function(){
  var tries = 0;
  function hook(){
    if(typeof switchScreen !== 'function'){
      if(tries++ < 20) setTimeout(hook, 100);
      return;
    }
    if(switchScreen.__salawatHooked) return;
    var orig = switchScreen;
    switchScreen = function(id){
      var r = orig.apply(this, arguments);
      if(id === 'screenSalawat') try{ initSalawat(); }catch(e){}
      if(id === 'screenQuiz') try{ initQuiz(); }catch(e){}
      if(id === 'screenMilad') try{ initMilad(); }catch(e){}
      try{ if(typeof I18N!=='undefined') I18N.apply(); }catch(e){}
      return r;
    };
    switchScreen.__salawatHooked = true;
    if(orig.__sfxWrapped) switchScreen.__sfxWrapped = true;
    if(orig.__gameHistHooked) switchScreen.__gameHistHooked = true;
  }
  hook();
})();


function isEnLang(){ try{ return typeof I18N!=='undefined' && I18N.lang==='en'; }catch(e){ return false; } }
function _(key){
  try{
    if(typeof I18N !== 'undefined' && I18N.t) return I18N.t(key);
  }catch(e){}
  return key;
}

/* ===== i18n · Tamil / English ===== */

/* ===== Nabi ﷺ Quiz (100 MCQ) ===== */
var quizState = { list: [], i: 0, score: 0, answered: false };

function shuffle(arr){
  var a = arr.slice();
  for(var i=a.length-1;i>0;i--){
    var j = Math.floor(Math.random()*(i+1));
    var tmp=a[i]; a[i]=a[j]; a[j]=tmp;
  }
  return a;
}


function isQuizLocked(){
  try{
    if(typeof meta!=='undefined' && meta.quizOnceDone) return true;
    if(localStorage.getItem('qg_quiz_once_done')==='1') return true;
  }catch(e){}
  return false;
}
function lockQuizOnce(score, total){
  try{
    if(total < 100) return;
    if(typeof meta!=='undefined'){
      meta.quizOnceDone = true;
      meta.quizOnceScore = score;
      meta.quizOnceTotal = total;
      meta.quizOnceAt = Date.now();
      if(typeof saveMeta==='function') saveMeta();
    }
    localStorage.setItem('qg_quiz_once_done', '1');
    localStorage.setItem('qg_quiz_once_score', String(score||0));
    localStorage.setItem('qg_quiz_once_total', String(total||100));
  }catch(e){}
}
function applyQuizLockUI(){
  var locked = isQuizLocked();
  var start = document.getElementById('quizStartBtn');
  var retry = document.getElementById('quizRetryBtn');
  var homeCard = document.querySelector('.quiz-intro-card');
  var isEn = (typeof isEnLang==='function' && isEnLang());
  var score = 0, total = 100;
  try{
    if(typeof meta!=='undefined' && meta.quizOnceScore!=null){ score = meta.quizOnceScore; total = meta.quizOnceTotal||100; }
    else {
      score = parseInt(localStorage.getItem('qg_quiz_once_score')||'0',10)||0;
      total = parseInt(localStorage.getItem('qg_quiz_once_total')||'100',10)||100;
    }
  }catch(e){}

  var lockNote = document.getElementById('quizLockNote');
  if(!lockNote && homeCard){
    lockNote = document.createElement('div');
    lockNote.id = 'quizLockNote';
    lockNote.style.cssText = 'margin-top:10px;padding:10px 12px;border-radius:12px;border:1px solid rgba(248,113,113,.45);background:rgba(127,29,29,.35);color:#fecaca;font-size:12px;font-weight:700;line-height:1.45;text-align:center';
    homeCard.appendChild(lockNote);
  }

  if(locked){
    if(start){
      start.disabled = true;
      start.textContent = isEn ? '🔒 Locked — Already played' : '🔒 பூட்டப்பட்டது — ஏற்கனவே விளையாடியுள்ளீர்கள்';
      start.style.opacity = '0.55';
      start.style.cursor = 'not-allowed';
      start.onclick = function(e){
        if(e) e.preventDefault();
        alert(isEn ? 'You can play this 100-question quiz only once.' : '100 கேள்வி வினாடி வினாவை ஒரு முறை மட்டுமே விளையாட முடியும்.');
      };
    }
    if(retry){
      retry.disabled = true;
      retry.style.display = 'none';
    }
    if(lockNote){
      lockNote.style.display = 'block';
      lockNote.innerHTML = isEn
        ? ('🔒 One-time quiz completed<br>Your score: <b>'+score+'/'+total+'</b><br>Cannot play again.')
        : ('🔒 ஒரு முறை மட்டும் — முடித்துவிட்டீர்கள்<br>உங்கள் மதிப்பெண்: <b>'+score+'/'+total+'</b><br>மீண்டும் விளையாட முடியாது.');
    }
  } else {
    if(start){
      start.disabled = false;
      start.style.opacity = '';
      start.style.cursor = '';
      // text restored by i18n if needed
      if(!start.textContent || start.textContent.indexOf('Locked')>=0 || start.textContent.indexOf('பூட்ட')>=0){
        start.textContent = isEn ? 'Start' : 'தொடங்கு / Start';
      }
    }
    if(retry){ retry.disabled = false; retry.style.display = ''; }
    if(lockNote) lockNote.style.display = 'none';
  }
}


function startQuiz(limit){
  if(isQuizLocked()){
    var isEn = (typeof isEnLang==='function' && isEnLang());
    alert(isEn ? 'You can play this 100-question quiz only once. Already completed.' : '100 கேள்வி வினாடி வினாவை ஒரு முறை மட்டுமே விளையாட முடியும். ஏற்கனவே முடித்துவிட்டீர்கள்.');
    try{ applyQuizLockUI(); }catch(e){}
    return;
  }
  var all = (typeof NABI_QUIZ !== 'undefined' && NABI_QUIZ) ? NABI_QUIZ : [];
  if(!all.length){ alert('Quiz data missing'); return; }
  var list = shuffle(all);
  if(limit && limit < list.length) list = list.slice(0, limit);
  quizState = { list: list, i: 0, score: 0, answered: false };
  document.getElementById('quizHome').style.display = 'none';
  document.getElementById('quizResult').style.display = 'none';
  document.getElementById('quizPlay').style.display = 'block';
  document.getElementById('quizTotal').textContent = String(list.length);
  document.getElementById('quizScore').textContent = '0';
  showQuizQuestion();
}

function showQuizQuestion(){
  var st = quizState;
  var q = st.list[st.i];
  if(!q){ endQuiz(); return; }
  st.answered = false;
  document.getElementById('quizNum').textContent = String(st.i+1);
  document.getElementById('quizScore').textContent = String(st.score);
  var pct = ((st.i) / st.list.length) * 100;
  document.getElementById('quizProgressFill').style.width = pct + '%';
  document.getElementById('quizQuestion').textContent = q.q;
  document.getElementById('quizFeedback').style.display = 'none';
  document.getElementById('quizNextBtn').style.display = 'none';
  var box = document.getElementById('quizOpts');
  var labels = ['A','B','C','D'];
  box.innerHTML = q.opts.map(function(opt, idx){
    return '<button type="button" class="quiz-opt" data-i="'+idx+'"><span class="quiz-opt-letter">'+labels[idx]+'</span><span class="quiz-opt-text">'+opt+'</span></button>';
  }).join('');
  box.querySelectorAll('.quiz-opt').forEach(function(btn){
    btn.onclick = function(){
      if(st.answered) return;
      st.answered = true;
      var pick = parseInt(btn.getAttribute('data-i'),10);
      var correct = q.ans;
      box.querySelectorAll('.quiz-opt').forEach(function(b){
        var bi = parseInt(b.getAttribute('data-i'),10);
        b.disabled = true;
        if(bi === correct) b.classList.add('correct');
        if(bi === pick && pick !== correct) b.classList.add('wrong');
      });
      var fb = document.getElementById('quizFeedback');
      var isEn = (typeof isEnLang==='function' && isEnLang());
      if(pick === correct){
        st.score++;
        fb.textContent = isEn ? '✅ Correct!' : '✅ சரி!';
        fb.className = 'quiz-feedback ok';
      } else {
        fb.textContent = (isEn ? '❌ Wrong. Answer: ' : '❌ தவறு. பதில்: ') + labels[correct] + ') ' + q.opts[correct];
        fb.className = 'quiz-feedback bad';
      }
      fb.style.display = 'block';
      document.getElementById('quizScore').textContent = String(st.score);
      document.getElementById('quizNextBtn').style.display = 'block';
      try{ if(typeof AudioFX!=='undefined'){ if(pick===correct && AudioFX.playSuccess) AudioFX.playSuccess(); else if(AudioFX.playClick) AudioFX.playClick(); } }catch(e){}
    };
  });
}

function ensureQuizMeta(){
  if(typeof meta === 'undefined') return;
  if(!meta.quizBoard) meta.quizBoard = [];
}
function saveQuizScore(score, total){
  try{
    ensureQuizMeta();
    var name = (meta.playerName || localStorage.getItem('qg_player_name') || 'வீரர்');
    var pct = total ? Math.round(score/total*100) : 0;
    var entry = { name: name, score: score, total: total, pct: pct, perfect: (score===total && total>=100), at: Date.now() };
    // keep best score per name for full 100-quiz
    var found = null;
    for(var i=0;i<meta.quizBoard.length;i++){
      if(meta.quizBoard[i].name === name && meta.quizBoard[i].total >= 100){ found = meta.quizBoard[i]; break; }
    }
    if(total >= 100){
      if(found){
        if(score > (found.score||0)){ found.score=score; found.pct=pct; found.perfect=(score===total); found.at=Date.now(); found.total=total; }
      } else {
        meta.quizBoard.push(entry);
      }
    } else {
      meta.quizBoard.push(entry);
    }
    // trim
    if(meta.quizBoard.length > 200) meta.quizBoard = meta.quizBoard.slice(-200);
    if(typeof saveMeta==='function') saveMeta();
  }catch(e){}
}
function renderQuizLeaderboard(){
  var box = document.getElementById('quizLeaderboard');
  if(!box) return;
  ensureQuizMeta();
  var isEn = (typeof isEnLang==='function' && isEnLang());
  // prefer full 100-question runs, sorted by score desc
  var board = (meta.quizBoard||[]).filter(function(e){ return (e.total||0) >= 100; });
  board.sort(function(a,b){ return (b.score||0)-(a.score||0) || (b.at||0)-(a.at||0); });
  // unique by name keep best
  var seen = {}, uniq = [];
  board.forEach(function(e){
    if(seen[e.name]) return;
    seen[e.name]=1;
    uniq.push(e);
  });
  board = uniq.slice(0, 20);
  if(!board.length){
    box.innerHTML = '<p class="quiz-lb-empty">'+(isEn?'No scores yet. Complete 100 questions!':'இன்னும் மதிப்பெண் இல்லை. 100 கேள்வி முடியுங்கள்!')+'</p>';
    return;
  }
  var medals = ['🥇','🥈','🥉'];
  var h = '<div class="quiz-lb-title">🏆 '+(isEn?'Quiz Leaderboard':'கேள்வி தரவரிசை')+'</div>';
  h += '<div class="quiz-lb-list">';
  board.forEach(function(e,i){
    var med = medals[i] || ('#'+(i+1));
    var star = e.perfect ? ' ✨' : '';
    h += '<div class="quiz-lb-row'+(e.perfect?' perfect':'')+'"><span class="quiz-lb-rank">'+med+'</span><span class="quiz-lb-name">'+e.name+star+'</span><span class="quiz-lb-score">'+e.score+'/'+e.total+'</span></div>';
  });
  h += '</div>';
  h += '<p class="quiz-lb-note">'+(isEn?'✨ = 100/100 correct · First join Telegram channel, then share your result there':'✨ = 100/100 சரி · முதலில் Telegram சேனலில் join செய்து, பிறகு share செய்யுங்கள்')+'</p>';
  box.innerHTML = h;
}
function buildQuizShareUrl(playerName, score, total){
  var isEn = (typeof isEnLang==='function' && isEnLang());
  var perfect = (score === total && total >= 100);
  var msg;
  if(isEn){
    msg = '🌙 Alhamdulillah!\n\n' +
      (perfect
        ? 'I scored PERFECT '+score+'/'+total+' on the Prophet ﷺ Seerah Quiz!\n\n'
        : 'I completed the Prophet ﷺ Seerah Quiz ('+total+' questions)!\n\n') +
      '👤 Name: ' + (playerName || 'Player') + '\n' +
      '✅ Score: ' + score + ' / ' + total + '\n' +
      '📖 Quran Garden · Q & A\n\n' +
      'Channel: https://t.me/islamic_post_1704';
  } else {
    msg = '🌙 அல்ஹம்துலில்லாஹ்!\n\n' +
      (perfect
        ? 'நான் குர்ஆன் தோட்டம் — கேள்வி & பதில்-ல் '+score+'/'+total+' முழு மதிப்பெண் பெற்றேன்!\n\n'
        : 'நான் குர்ஆன் தோட்டம் — கேள்வி & பதில் '+total+' கேள்விகளை முடித்தேன்!\n\n') +
      '👤 பெயர்: ' + (playerName || 'வீரர்') + '\n' +
      '✅ மதிப்பெண்: ' + score + ' / ' + total + '\n' +
      '📖 Quran Garden · கேள்வி & பதில்\n\n' +
      'சேனல்: https://t.me/islamic_post_1704';
  }
  return 'https://t.me/share/url?url=' + encodeURIComponent('https://t.me/islamic_post_1704') +
    '&text=' + encodeURIComponent(msg);
}

function openTelegramShare(shareUrl){
  // Mobile browsers often block window.open from timeouts — try multiple ways
  try {
    var a = document.createElement('a');
    a.href = shareUrl;
    a.target = '_blank';
    a.rel = 'noopener';
    document.body.appendChild(a);
    a.click();
    setTimeout(function(){ try{ a.remove(); }catch(e){} }, 1000);
  } catch(e1) {
    try { window.open(shareUrl, '_blank'); } catch(e2) {
      try { window.location.href = shareUrl; } catch(e3) {}
    }
  }
}

